window.GRAMMAR = (window.GRAMMAR || []).concat([
  {"id":"d1725293495956","pattern":"〜(ら)れるだけ〜","core":"(ら)れるだけ〜","blankTarget":"けるだけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞を２回用いて接続し、可能な限りの最大の程度を表します。 他にも「できるだけ～する」という言い方もあります。","en":"as much as one can; as ... as possible","ko":"할 수 있는 만큼; 가능한 한"},"formation":{"ja":"動可能形＋だけ＋動詞 / 動可能形＋だけの＋名詞","en":"動可能形＋だけ＋動詞 / 動可能形＋だけの＋名詞","ko":"動可能形＋だけ＋動詞 / 動可能形＋だけの＋名詞"},"examples":[{"ja":"ご飯は炊けるだけ炊いて、毎回食べたい量に小分けにして冷凍している。食べるときはチンして食べると手間もかからない。","en":"I cook as much rice as I can, divide it into portions, and freeze it. When I eat, I just microwave it, so it takes no effort.","ko":"밥은 할 수 있는 만큼 지어서 먹고 싶은 양만큼 소분해 냉동해 둔다. 먹을 때는 전자레인지에 돌리기만 하면 되니 손이 안 간다."}],"similar":[]},
  {"id":"d1725293495957","pattern":"〜(る)だけ〜","core":"(る)だけ〜","blankTarget":"だけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞を２回用いて接続し、その動作を話者が十分だと思う程度量行うことを表します。 似ている文法に「【Ｎ２文法】～（ら）れるだけ～」がありますが、こちらは可能な限りの最大の程度量を表す点で異なります。","en":"do as much as one deems enough; do all one can","ko":"충분히 …만큼 하다; 할 만큼 다 하다"},"formation":{"ja":"動詞辞書形＋だけ＋動詞 / できるだけ（のことは）する / やれるだけ（のことは）やる","en":"動詞辞書形＋だけ＋動詞 / できるだけ（のことは）する / やれるだけ（のことは）やる","ko":"動詞辞書形＋だけ＋動詞 / できるだけ（のことは）する / やれるだけ（のことは）やる"},"examples":[{"ja":"やるだけやった。あとは結果を待つだけだ。","en":"I've done all I can. Now all that's left is to wait for the result.","ko":"할 만큼은 다 했다. 이제 결과를 기다릴 뿐이다."}],"similar":[]},
  {"id":"d1725293495882","pattern":"〜か〜ないかのうちに","core":"か〜ないかのうちに","blankTarget":"か","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞の辞書形、動た形とナイ形を使って接続し、実際は前件の動作が行われる直前に後件が発生したことを表します。前件と後件の動作がほぼ同時に発生したとも捉えられます。","en":"hardly had ... when; as soon as; almost before","ko":"…하자마자; …하기 무섭게"},"formation":{"ja":"動詞辞書形＋か＋動ない形＋ないかのうちに / 動た形＋か＋動ない形＋ないかのうちに","en":"動詞辞書形＋か＋動ない形＋ないかのうちに / 動た形＋か＋動ない形＋ないかのうちに","ko":"動詞辞書形＋か＋動ない形＋ないかのうちに / 動た形＋か＋動ない形＋ないかのうちに"},"examples":[{"ja":"日曜休んだか休んでないかのうちに終わってまた月曜。","en":"Sunday was over almost before I could rest, and it was Monday again.","ko":"일요일은 쉬었는지 안 쉬었는지 모를 사이에 끝나고 또 월요일이다."}],"similar":[]},
  {"id":"d1725293495881","pattern":"〜かけ／〜かけの／〜かける","core":"かけ","blankTarget":"かけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"動ます形に接続し、まだ途中で完全にし終わっていない状態を表します。 例えば「壊れかけ」は、まだ完全に壊れてはいないが完全に壊れた状態へと進行している状態を指します。 「～かけ」自体は名詞として扱います。 １はコップにいっぱいのジュースが入っていますので、まだ飲んでいない状態です。 ２は少し飲みましたが、まだ全部飲んでいません。このような状態を「飲みかけ」と言います。 ３は全部飲んでしまいましたので、飲み終わっています。","en":"half-done; in the middle of; about to","ko":"…하다 만; …하는 중; 거의 …될 참"},"formation":{"ja":"動ます形＋かけ / 動ます形＋かけの＋名詞 / 動ます形＋かける／かけている","en":"動ます形＋かけ / 動ます形＋かけの＋名詞 / 動ます形＋かける／かけている","ko":"動ます形＋かけ / 動ます形＋かけの＋名詞 / 動ます形＋かける／かけている"},"examples":[{"ja":"作りかけのパズル","en":"An unfinished puzzle","ko":"만들다 만 퍼즐"}],"similar":[]},
  {"id":"d1725293495891","pattern":"〜かと言うと／かと言えば","core":"かと言うと","blankTarget":"かと言えば","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの用法があります。 ①実はそうではない まず前件で前提となる事実を述べ、その事実から必然的に導き出される結果を否定します。前件では「【Ｎ２文法】～からといって／からって／からとて」が呼応することもあり、後件では「～ではない」「必ずしも～とは限らない」などの言い方で否定します。 【Ａ】。しかし【Ｂ】かと言うと【そうではない】 【Ａ】からと言って【Ｂ】かと言うと【そうではない】 ②事情説明 疑問詞を伴った句について疑問を提示し、その疑問に自ら答え、解説を加える用法です。この文型はその疑問に対してフォーカスを当てる役割があります。 「どちらかと言うと（说起来／总的来说）」は慣用的に用います。","en":"as for whether...; not necessarily so; if you ask why, it's because...","ko":"…인지 하면; 꼭 그런 것은 아니다; 왜냐하면"},"formation":{"ja":"①動詞普通形＋（の）かと言うと / イ形容詞普通形＋（の）かと言うと / ナ形容詞語幹＋（なの）かと言うと / 名詞＋（なの／であるの）かと言うと / ②疑問句＋かと言うと","en":"①動詞普通形＋（の）かと言うと / イ形容詞普通形＋（の）かと言うと / ナ形容詞語幹＋（なの）かと言うと / 名詞＋（なの／であるの）かと言うと / ②疑問句＋かと言うと","ko":"①動詞普通形＋（の）かと言うと / イ形容詞普通形＋（の）かと言うと / ナ形容詞語幹＋（なの）かと言うと / 名詞＋（なの／であるの）かと言うと / ②疑問句＋かと言うと"},"examples":[{"ja":"絵が上手であれば誰でも漫画家になれるかと言えば、そうとは限らない。","en":"It doesn't necessarily follow that anyone who draws well can become a manga artist.","ko":"그림을 잘하면 누구나 만화가가 될 수 있느냐 하면 그렇지도 않다."}],"similar":[]},
  {"id":"d1725293495892","pattern":"〜かと思いきや／かと思ったら／かと思えば／かと思うと","core":"かと思いきや","blankTarget":"かと思えば","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"予想外な出来事、意外な出来事が発生したことを表します。 話者の驚きや意外の感情が含まれます。そのため、自分自身のことには使えません。必ず他人や周囲の状況に対して用います。 接続詞として単独で用いることもできます。例文（２）。 「（一体）何事かと思ったら」「何が起きたのかと思ったら」「誰かと思ったら」「何かと思ったら」等の疑問詞が含まれる表現は慣用的に用いられます。例文（７）（８）。","en":"just when I thought...; contrary to expectations","ko":"…인가 싶었는데 (의외로); 막 …했더니"},"formation":{"ja":"動詞普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / イ形普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / ナ形語幹＋かと思いきや／かと思ったら／かと思えば／かと思うと / 名詞＋かと思いきや／かと思ったら／かと思えば／かと思うと","en":"動詞普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / イ形普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / ナ形語幹＋かと思いきや／かと思ったら／かと思えば／かと思うと / 名詞＋かと思いきや／かと思ったら／かと思えば／かと思うと","ko":"動詞普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / イ形普通形＋かと思いきや／かと思ったら／かと思えば／かと思うと / ナ形語幹＋かと思いきや／かと思ったら／かと思えば／かと思うと / 名詞＋かと思いきや／かと思ったら／かと思えば／かと思うと"},"examples":[{"ja":"ここ最近暑くなったかと思えば気温が低くかったりの不安定な日が続いてます。","en":"Lately the weather has been unstable, turning hot one moment and cold the next.","ko":"요즘은 더워졌나 싶으면 기온이 낮아지기도 하는 등 불안정한 날이 이어지고 있다."}],"similar":[]},
  {"id":"d1725293495893","pattern":"〜かと思ったら／かと思いきや／かと思うと","core":"かと思ったら","blankTarget":"と思ったら","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項直後に後項がすぐ発生することを表します。 ただし後項には話者にとって想定外のこと、意外なことが述べられ、しばしば驚きや呆れのニュアンスが含まれます。 既に発生したことについて述べるので、後項はほぼ過去形となります。 また、想定外のことについて述べるので自分自身の行為に使うことはできず、他人の状況に対して客観的に述べる用法です。 文型中の「か」は、話者が疑問を抱いているときや判断に迷っているときに接続されます。","en":"no sooner had... than...; just when one thought...","ko":"…인가 했더니; …하자마자"},"formation":{"ja":"文＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動た形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動詞辞書形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 名詞＋（か／なのか）と思いきや","en":"文＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動た形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動詞辞書形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 名詞＋（か／なのか）と思いきや","ko":"文＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動た形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 動詞辞書形＋（か／のか）と思ったら／（か／のか）と思いきや／（か／のか）と思うと / 名詞＋（か／なのか）と思いきや"},"examples":[{"ja":"怒られると思ったら慰められた。","en":"I thought I was going to be scolded, but instead I was comforted.","ko":"혼날 줄 알았더니 오히려 위로를 받았다."}],"similar":[]},
  {"id":"d1725293495889","pattern":"〜から〜にわたって／にわたり／にわたる／にわたった","core":"から〜にわたって","blankTarget":"から","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～から～まで」と同じく時間や空間の範囲を表します。ただし、その範囲の起点と終点がはっきりしていて、現象が範囲全体に広がっているようなニュアンスを持っています。範囲は面状です。 起点を述べる必要がなければ、「～から」を省略することができます。 漢字は「渡って」を使います。 「長年にわたって／長きにわたって」は長期間続くことを表す慣用表現です。","en":"from... to...; over; spanning","ko":"…에서 …에 걸쳐; …부터 …까지"},"formation":{"ja":"名詞＋から＋名詞＋にわたって / 名詞＋から＋名詞＋にわたり / 名詞＋から＋名詞＋にわたる（＋名詞） / 名詞＋から＋名詞＋にわたった（＋名詞）","en":"名詞＋から＋名詞＋にわたって / 名詞＋から＋名詞＋にわたり / 名詞＋から＋名詞＋にわたる（＋名詞） / 名詞＋から＋名詞＋にわたった（＋名詞）","ko":"名詞＋から＋名詞＋にわたって / 名詞＋から＋名詞＋にわたり / 名詞＋から＋名詞＋にわたる（＋名詞） / 名詞＋から＋名詞＋にわたった（＋名詞）"},"examples":[{"ja":"親から子と世代にわたって生活保護の人々もいる。","en":"There are people on welfare across generations, from parents to children.","ko":"부모에서 자식으로 세대에 걸쳐 생활보호를 받는 사람들도 있다."}],"similar":[]},
  {"id":"d1725293495886","pattern":"〜からいいようなものの／からいいものの／からよかったものの","core":"からいいようなものの","blankTarget":"からいいようなものの","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"今回は最悪の事態を回避することができたが、状況は依然として良くはないことを表します。相手に責任を問うようなニュアンスを含みます。","en":"it's just as well that...; only because... (but still not acceptable)","ko":"…라서 다행이지 (그렇지 않았다면 큰일)"},"formation":{"ja":"文の普通形＋からいいようなものの","en":"文の普通形＋からいいようなものの","ko":"文の普通形＋からいいようなものの"},"examples":[{"ja":"怪我で済んだからいいようなものの、死亡事故になっていたら会社側は責任とってくれたのだろうか。","en":"It's only fortunate that it ended with an injury; if it had been a fatal accident, would the company have taken responsibility?","ko":"부상으로 끝났으니 다행이지, 사망 사고가 났더라면 회사가 책임을 졌을까."}],"similar":[]},
  {"id":"d1725293495887","pattern":"〜からこそ","core":"からこそ","blankTarget":"からこそ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"理由や原因を強調する文法です。 理由はまさにそれであり、それ以外ではないというニュアンスを持ちます。 主に良い内容に用い、主観的な判断に基づくものです。","en":"precisely because; just because (emphasized)","ko":"바로 …이기 때문에; …이기에"},"formation":{"ja":"名詞＋だからこそ / な形容詞語幹＋だ／である＋からこそ / い形容詞普通形＋からこそ / 動詞普通形＋からこそ","en":"名詞＋だからこそ / な形容詞語幹＋だ／である＋からこそ / い形容詞普通形＋からこそ / 動詞普通形＋からこそ","ko":"名詞＋だからこそ / な形容詞語幹＋だ／である＋からこそ / い形容詞普通形＋からこそ / 動詞普通形＋からこそ"},"examples":[{"ja":"普段こういったことは言わないけど、好きな人だからこそ言っておきたかった。","en":"I don't usually say things like this, but precisely because it's the person I like, I wanted to say it.","ko":"평소엔 이런 말 안 하는데, 좋아하는 사람이기에 꼭 말해 두고 싶었다."}],"similar":[]},
  {"id":"d1725293495890","pattern":"〜からといって／からって／からとて","core":"からといって","blankTarget":"からといって","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項で述べる原因一つだけでは、後項は十分に成り立たないこと、そうは言いきれないことを表します。 口語は「からって」、文語には「からとて」があります。全て同じ意味です。","en":"just because... (doesn't mean); not necessarily because","ko":"…라고 해서 (반드시 …는 아니다)"},"formation":{"ja":"名詞＋だからといって／だからって／だからとて / な形容詞＋だからといって／だからって／だからとて / い形容詞＋からといって／からって／からとて / 動詞普通形＋からといって／からって／からとて","en":"名詞＋だからといって／だからって／だからとて / な形容詞＋だからといって／だからって／だからとて / い形容詞＋からといって／からって／からとて / 動詞普通形＋からといって／からって／からとて","ko":"名詞＋だからといって／だからって／だからとて / な形容詞＋だからといって／だからって／だからとて / い形容詞＋からといって／からって／からとて / 動詞普通形＋からといって／からって／からとて"},"examples":[{"ja":"電車やバスで席を譲らなかったからといって、わざわざ批判されるようなことではない。","en":"Not giving up your seat on a train or bus isn't something you need to be criticized for.","ko":"전철이나 버스에서 자리를 양보하지 않았다고 해서 굳이 비난받을 일은 아니다."}],"similar":[]},
  {"id":"d1725293495888","pattern":"〜からには","core":"からには","blankTarget":"からには","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項では何らかの責任や決意・決心を表し、後項ではその前項に対する責任や義務を果たす内容が述べられます。 多くの場合、後項では「～なければならない」や「～べき」、「～つもり」など義務や決意などを表す意志性が強い表現が用いられます。","en":"now that; since (one has decided to do something)","ko":"…한 이상; …하기로 한 바에야"},"formation":{"ja":"動詞普通形＋からには / い形普通形＋からには / 名詞＋である＋からには / 名詞＋ではない＋からには","en":"動詞普通形＋からには / い形普通形＋からには / 名詞＋である＋からには / 名詞＋ではない＋からには","ko":"動詞普通形＋からには / い形普通形＋からには / 名詞＋である＋からには / 名詞＋ではない＋からには"},"examples":[{"ja":"やるからには１位を取りたい。","en":"Since I'm going to do it, I want to take first place.","ko":"할 거라면 1등을 하고 싶다."}],"similar":[]},
  {"id":"d1725293495894","pattern":"〜きり／っきり","core":"きり","blankTarget":"っきり","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"名詞に接続すると「～だけ」、動ます形に接続すると「全力で／完全に／ずっと」の意味を表します。","en":"only; just; completely; all the way","ko":"…뿐; …만; …한 채로; 내내"},"formation":{"ja":"①名詞＋きり／っきり / ②動ます形＋きり／っきり","en":"①名詞＋きり／っきり / ②動ます形＋きり／っきり","ko":"①名詞＋きり／っきり / ②動ます形＋きり／っきり"},"examples":[{"ja":"部屋で何日もずっと籠りっきりで作業していた。","en":"I stayed cooped up in my room for days, working the whole time.","ko":"방에 며칠 내내 틀어박혀서 작업했다."}],"similar":[]},
  {"id":"d1725293495902","pattern":"〜くらいだから／くらいなので／ぐらいだから／ぐらいなので","core":"くらいだから","blankTarget":"ぐらいだから","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話し手の主観的な判断や推測を述べる文型です。 前件にはある動作や状態の程度（過去のことや事実）が述べられ、後件ではその程度から推測される主観的な判断を述べます。 そのため、後件では「～だろう」「～でしょう」「～はずだ」「～と思う」などの話し手の推量を表す表現が呼応しやすいです。","en":"given that...; judging from how much...","ko":"…할 정도이니까; …인 만큼"},"formation":{"ja":"動詞普通形＋くらい／ぐらい～ / イ形普通形＋くらい／ぐらい～ / ナ形語幹＋な／だった＋くらい／ぐらい～ / 名詞＋だった＋くらい／ぐらい～","en":"動詞普通形＋くらい／ぐらい～ / イ形普通形＋くらい／ぐらい～ / ナ形語幹＋な／だった＋くらい／ぐらい～ / 名詞＋だった＋くらい／ぐらい～","ko":"動詞普通形＋くらい／ぐらい～ / イ形普通形＋くらい／ぐらい～ / ナ形語幹＋な／だった＋くらい／ぐらい～ / 名詞＋だった＋くらい／ぐらい～"},"examples":[{"ja":"あそこのケーキ屋、テレビで紹介されるぐらいだから、さぞ美味しいんだろう。","en":"That cake shop must be delicious, given that it was featured on TV.","ko":"저 과자점은 TV에 소개될 정도이니 틀림없이 맛있겠지."}],"similar":[]},
  {"id":"d1725293495864","pattern":"〜げ","core":"げ","blankTarget":"げ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"外から見た表面的様子から、対象の感情、感覚、性格、属性など推測・予想するという意味を持っています。断定を避ける婉曲表現なので、話者の主張を和らげる働きがあります。「～らしい」「～のようだ」等と同じような意味です。 「～げ」は動詞、イ形容詞、ナ形容詞について、それらをナ形容詞化する接尾辞です。 接続できる語は少なく生産性は低い上、ほとんどの語は慣用的に用いられていますが、若者の間では以前よりも頻繁に使われるようになってきており、これまでなかった新たな語が作られることが多くなっています。 ～げ気配や雰囲気から感じられる。主体の主観的な印象による感じを表現する。助動詞「～そう」主体が直接知覚できない感情・感覚・属性を予想する。感情・感覚・属性は、様子や文脈から想定されるものでなければならない。 イ形容詞、ナ形容詞を名詞化するものに「【Ｎ３文法】～さ」があります。 「彼女は可愛さがない」と「彼女は可愛げがない」では、後者が正しいです。「～さ」は客観的な程度の大小を表すだけで、話者の主観的な意見が含まれる場合に「～さ」は使いにくくなります。 「ありげ」は「ありそう」という意味です。 それとは意味的に逆の表現に「無さげ（なさげ）」（なさそう）があります。これは文法的に破格です。「良さげ（よさげ）」（よさそう）と合わせて若者言葉として使われています。","en":"-looking; seeming; appearing","ko":"…한 기색; …스러운 모습"},"formation":{"ja":"動ます形＋げ（ありげ） / い形容詞語幹＋げ / な形容詞語幹＋げ / ※なさげ / ～げな＋名詞","en":"動ます形＋げ（ありげ） / い形容詞語幹＋げ / な形容詞語幹＋げ / ※なさげ / ～げな＋名詞","ko":"動ます形＋げ（ありげ） / い形容詞語幹＋げ / な形容詞語幹＋げ / ※なさげ / ～げな＋名詞"},"examples":[{"ja":"彼女はなんだか悲しげな様子だ。","en":"She looks somehow sad.","ko":"그녀는 어쩐지 슬픈 기색이다."}],"similar":[]},
  {"id":"d1725293495898","pattern":"〜ことか／ことだろう／ことだろうか","core":"ことか","blankTarget":"ことか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"感情を強調します。 前件には「どれだけ」「どれほど」「どんなに」「なんと」「なんて」などの疑問詞が呼応します。","en":"how...!; what...!","ko":"얼마나 …인지; 정말 …하구나"},"formation":{"ja":"動詞普通形＋ことか / い形容詞普通形＋ことか / な形容詞＋である／な＋ことか","en":"動詞普通形＋ことか / い形容詞普通形＋ことか / な形容詞＋である／な＋ことか","ko":"動詞普通形＋ことか / い形容詞普通形＋ことか / な形容詞＋である／な＋ことか"},"examples":[{"ja":"私たちこうやって再会できたことが、どんなに嬉しいことか。","en":"How happy I am that we could meet again like this.","ko":"이렇게 다시 만날 수 있다니 얼마나 기쁜지."}],"similar":[]},
  {"id":"d1725293495899","pattern":"〜ことから","core":"ことから","blankTarget":"ことから","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"原因や理由、根拠を表します。 後項では、前項で示された原因や根拠によって導かれる結果が述べられます。","en":"because; from the fact that; judging from","ko":"…한 데서; …때문에; …로 보아"},"formation":{"ja":"動詞普通形＋ことから / い形容詞普通形＋ことから / な形容詞語幹＋な＋ことから / 名詞＋である＋ことから","en":"動詞普通形＋ことから / い形容詞普通形＋ことから / な形容詞語幹＋な＋ことから / 名詞＋である＋ことから","ko":"動詞普通形＋ことから / い形容詞普通形＋ことから / な形容詞語幹＋な＋ことから / 名詞＋である＋ことから"},"examples":[{"ja":"「ねこ」は昼間よく寝ることから、「寝子」と名付けられたことに由来すると言われている。","en":"It is said the name \"Neko\" comes from the fact that cats sleep a lot during the day.","ko":"\"네코\"라는 이름은 낮에 잠을 많이 자는 데서 유래했다고 한다."}],"similar":[]},
  {"id":"d1725293495897","pattern":"〜ことだろう／ことでしょう","core":"ことだろう","blankTarget":"ことだろう","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"推測を表します。前件に「さぞ」「さぞかし」が呼応することもあります。 「だろう／でしょう」単体でも推測を表しますが、「ことだろう／ことでしょう」はさらに丁重で書き言葉的な表現で、話者の感情が含まれます。 情景、情緒、感情を前面に出せる文法です。","en":"must be...; surely...; how... it must be","ko":"얼마나 …일까; 분명 …이겠지"},"formation":{"ja":"動詞普通形＋ことだろう／ことでしょう / イ形普通形＋ことだろう／ことでしょう / ナ形語幹＋な／である＋ことだろう／ことでしょう","en":"動詞普通形＋ことだろう／ことでしょう / イ形普通形＋ことだろう／ことでしょう / ナ形語幹＋な／である＋ことだろう／ことでしょう","ko":"動詞普通形＋ことだろう／ことでしょう / イ形普通形＋ことだろう／ことでしょう / ナ形語幹＋な／である＋ことだろう／ことでしょう"},"examples":[{"ja":"女の子は可愛い服をいっぱい着れて、さぞかし毎日楽しいことだろう。","en":"Girls must have so much fun every day, getting to wear lots of cute clothes.","ko":"여자아이들은 귀여운 옷을 잔뜩 입을 수 있으니 매일 얼마나 즐거울까."}],"similar":[]},
  {"id":"d1725293495901","pattern":"〜ことにしている","core":"ことにしている","blankTarget":"ことにしている","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"既に定着した個人の習慣を述べるときに用いる文法です。 文化に根付いた習慣、礼儀には用いることができません。 ✕日本人はお風呂に入ることにしている。 〇日本人はお風呂に入る。 似ている文法に「【Ｎ４文法】～ようにする／ないようにする」があります。 こちらは「～ようにしている」とテイル形にすることで、同じく習慣を表す意味となります。ただし、「～ようにする」は努力の跡が伺える点でニュアンスが若干異なります。 〇寝る前は必ずお風呂に入ることにしている。 〇寝る前は必ずお風呂に入るようにしている。","en":"make it a rule to; have made a habit of","ko":"…하기로 정해 두다; 습관적으로 …하다"},"formation":{"ja":"動詞辞書形＋ことにしている","en":"動詞辞書形＋ことにしている","ko":"動詞辞書形＋ことにしている"},"examples":[{"ja":"寝る前は必ずお風呂に入ることにしている。","en":"I make it a rule to take a bath before going to bed.","ko":"잠들기 전에는 반드시 목욕을 하기로 정해 두었다."}],"similar":[]},
  {"id":"d1725293495900","pattern":"〜ことにはならない","core":"ことにはならない","blankTarget":"ことにはならない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"その程度には十分達していないことを表します。「～だとは言えない」とほぼ同義です。","en":"doesn't amount to; doesn't mean that; cannot be considered","ko":"…는 것이 되지 않는다; …라고 할 수는 없다"},"formation":{"ja":"動詞辞書形／動た形＋（という）ことにはならない / イ形普通形＋（という）ことにはならない / ナ形語幹＋（（だ）という）ことにはならない","en":"動詞辞書形／動た形＋（という）ことにはならない / イ形普通形＋（という）ことにはならない / ナ形語幹＋（（だ）という）ことにはならない","ko":"動詞辞書形／動た形＋（という）ことにはならない / イ形普通形＋（という）ことにはならない / ナ形語幹＋（（だ）という）ことにはならない"},"examples":[{"ja":"人を嫌うのは自由だが、それで人を傷付けていいことにはならない。","en":"You're free to dislike people, but that doesn't make it okay to hurt them.","ko":"사람을 싫어하는 건 자유지만, 그렇다고 해서 사람을 상처 입혀도 되는 것은 아니다."}],"similar":[]},
  {"id":"d1725293495896","pattern":"〜こなす","core":"こなす","blankTarget":"こなし","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"動ます形に接続し、身につけた技術や能力で完璧に行うことを表します。「熟す」という漢字があてられますが、平仮名で書くのが一般的です。 乗る、使う、やる、歌う、踊る、弾く、着る等…、接続できる動詞はあまり多くありません。 例文（７）のように、「こなす（处理／做完）」と単独で用いることもできます。 また、例文（８）のように「数をこなす（做大量的工作）」のような定型表現もあります。","en":"handle skillfully; have mastered; do ... with ease","ko":"능숙하게 해내다; 자유자재로 다루다"},"formation":{"ja":"動ます形＋こなす","en":"動ます形＋こなす","ko":"動ます形＋こなす"},"examples":[{"ja":"ギターを弾きこなしている姿はとても魅力的に見える。","en":"The way he plays the guitar so skillfully looks really attractive.","ko":"기타를 능숙하게 연주하는 모습은 무척 매력적으로 보인다."}],"similar":[]},
  {"id":"d1725293496016","pattern":"〜ざるを得ない","core":"ざるを得ない","blankTarget":"ざるを得ない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"それ以外に他の方法や選択肢がないことを表します。本当はしたくないのに、何らかの要因によってしなければならなくなったというニュアンスがあります。 多くは書き言葉として用いられ、「する」は「せざるを得ない」となります。","en":"have no choice but to; cannot help but","ko":"…하지 않을 수 없다; …해야만 한다"},"formation":{"ja":"動ない形＋ざるを得ない","en":"動ない形＋ざるを得ない","ko":"動ない形＋ざるを得ない"},"examples":[{"ja":"彼のことは好きではないが、その実力は認めざるを得ない。","en":"I don't like him, but I have to admit his ability.","ko":"그를 좋아하지는 않지만 그 실력은 인정하지 않을 수 없다."}],"similar":[]},
  {"id":"d1725293495959","pattern":"〜されるまま／されるがままに","core":"されるまま","blankTarget":"れるがままに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"他人の意向や自然の成り行きに従って物事を行うことを表します。 自分の意志は少しも含まれていません。 多くは良くないことに用います。","en":"as one is told; at the mercy of; letting oneself be...","ko":"…되는 대로; …시키는 대로"},"formation":{"ja":"動詞受身形＋（が）まま","en":"動詞受身形＋（が）まま","ko":"動詞受身形＋（が）まま"},"examples":[{"ja":"どう発音するか分からなくて、言われるがままに必死で先生の真似をした。","en":"I didn't know how to pronounce it, so I desperately imitated the teacher as told.","ko":"어떻게 발음하는지 몰라서 시키는 대로 필사적으로 선생님을 따라 했다."}],"similar":[]},
  {"id":"d1725293496018","pattern":"〜ずにはいられない／ないではいられない","core":"ずにはいられない","blankTarget":"ずにはいられない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"自分の意志とは関係なく、自然に動作が引き起こされることを表します。","en":"can't help doing; can't resist doing","ko":"…하지 않을 수 없다; 저절로 …하게 된다"},"formation":{"ja":"動ない形＋ずにはいられない / 動ない形＋ないではいられない","en":"動ない形＋ずにはいられない / 動ない形＋ないではいられない","ko":"動ない形＋ずにはいられない / 動ない形＋ないではいられない"},"examples":[{"ja":"純真無垢な主人公の恋を応援せずにはいられない。","en":"I can't help rooting for the pure-hearted protagonist's love.","ko":"순수한 주인공의 사랑을 응원하지 않을 수 없다."}],"similar":[]},
  {"id":"d1725293495962","pattern":"〜たいだけ〜","core":"たいだけ〜","blankTarget":"たいだけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞を２回用いて接続し、気が済むまでずっと行うことを表します。 「ほしいだけ～する」という言い方もあります。","en":"as much as one wants; to one's heart's content","ko":"하고 싶은 만큼; 실컷"},"formation":{"ja":"動ます形＋たいだけ＋動詞","en":"動ます形＋たいだけ＋動詞","ko":"動ます形＋たいだけ＋動詞"},"examples":[{"ja":"大学には行きたくない。遊びたいだけ遊んで３０歳で死にたい。","en":"I don't want to go to university. I want to play as much as I like and die at thirty.","ko":"대학에는 가고 싶지 않다. 실컷 놀다가 서른 살에 죽고 싶다."}],"similar":[]},
  {"id":"d1725293495961","pattern":"〜たいばかりに／〜が欲しいばかりに","core":"たいばかりに","blankTarget":"たいばかりに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"目標や目的を表す語について、理由や原因を表します。 後件にはその目標を達成するために苦労して行った事や、手段を選ばずに行った事などが述べられます。 主語の一心不乱な様子が感じられる文型です。","en":"just because one wants to...; out of a desire to...","ko":"…하고 싶은 나머지; …고 싶다는 이유만으로"},"formation":{"ja":"動ます形＋たいばかりに / 名詞＋が欲しいばかりに","en":"動ます形＋たいばかりに / 名詞＋が欲しいばかりに","ko":"動ます形＋たいばかりに / 名詞＋が欲しいばかりに"},"examples":[{"ja":"評価されたいばかりに、やりたくもない仕事を引き受けてしまった。","en":"Just because I wanted to be appreciated, I ended up taking on work I didn't even want to do.","ko":"인정받고 싶은 나머지 하기도 싫은 일을 떠맡고 말았다."}],"similar":[]},
  {"id":"d1725293495853","pattern":"〜だけ〜て","core":"だけ〜て","blankTarget":"だけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞を２回用いて接続します。 その動作だけ行い、それ以外のやるべきことはやらないというニュアンスを持っています。","en":"only do... and nothing else","ko":"…하기만 하고 (그 밖엔 안 하다)"},"formation":{"ja":"動詞辞書形＋だけ＋動て形","en":"動詞辞書形＋だけ＋動て形","ko":"動詞辞書形＋だけ＋動て形"},"examples":[{"ja":"平日は仕事するだけして、休日は家で死んだように寝ている。","en":"On weekdays I do nothing but work, and on days off I lie at home like the dead.","ko":"평일에는 일만 하고, 휴일에는 집에서 죽은 듯이 누워 지낸다."}],"similar":[]},
  {"id":"d1725293495854","pattern":"〜だけ〜てみる／だけ〜てみよう","core":"だけ〜てみる","blankTarget":"だけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞を２回用いて接続します。 「何もしないよりはやってみたほうがいいから～してみる」という意味です。 後件は「～てみる」「～てみよう」など話者の意向を表す表現が来やすいです。","en":"give it a try anyway; try as much as one can","ko":"되는대로 해 보다; 일단 해 보다"},"formation":{"ja":"動詞辞書形＋だけ＋動て形＋みる / 動詞辞書形＋だけ＋動て形＋みよう","en":"動詞辞書形＋だけ＋動て形＋みる / 動詞辞書形＋だけ＋動て形＋みよう","ko":"動詞辞書形＋だけ＋動て形＋みる / 動詞辞書形＋だけ＋動て形＋みよう"},"examples":[{"ja":"失敗するかもしれないけどやるだけやってみようか。","en":"I might fail, but let's do all we can and give it a try.","ko":"실패할지도 모르지만 할 만큼 해 보고 그래 보자."}],"similar":[]},
  {"id":"d1725293495848","pattern":"〜だけ／分だけ(ぶんだけ)","core":"だけ","blankTarget":"だけ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"程度量を表します。 前件の程度に相当する事態が発生したり、その程度に相応しい量の変化がもたらされることを後件で述べます。 「数」「量」などの数量を表す語につくときは「分」が省略可能になります。","en":"to the extent of; as much as; the more... the...","ko":"…한 만큼; …에 상응하여"},"formation":{"ja":"名詞＋（の）分 / 名詞＋だけ / 名詞＋の分だけ / な形容詞語幹＋な分 / な形容詞語幹＋だけ","en":"名詞＋（の）分 / 名詞＋だけ / 名詞＋の分だけ / な形容詞語幹＋な分 / な形容詞語幹＋だけ","ko":"名詞＋（の）分 / 名詞＋だけ / 名詞＋の分だけ / な形容詞語幹＋な分 / な形容詞語幹＋だけ"},"examples":[{"ja":"「ありがとう」の言葉の数だけ人と人の距離が縮まる。","en":"The more the words \"thank you\" are exchanged, the closer people grow.","ko":"\"고마워\"라는 말이 오가는 만큼 사람 사이의 거리도 가까워진다."}],"similar":[]},
  {"id":"d1725293495849","pattern":"〜だけに／だけあって(原因)","core":"だけに","blankTarget":"だけに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"理由を表す文型です。理由の「から」や「ので」に言い換えることができますが、それらよりも前項の理由を強調する言い方として用いられます。主観的な表現で、良い評価も悪い評価も可能です。 用法は２つあります。 ①前件の理由から必然的に導き出される結論や状態 「なおさら」が呼応することもあります。 ②予想と結果の相反／意外な結果 「かえって」「逆に」が呼応することもあります。 多くの場合は自分の予想とは反する内容が後件で述べられるので、良くない内容が来やすいです。","en":"precisely because; just because; all the more so since","ko":"…인 만큼; …이기 때문에 더욱"},"formation":{"ja":"動詞普通形＋だけに / な形容詞＋である／なだけに / い形容詞＋だけに / 名詞（＋である／な）＋だけに","en":"動詞普通形＋だけに / な形容詞＋である／なだけに / い形容詞＋だけに / 名詞（＋である／な）＋だけに","ko":"動詞普通形＋だけに / な形容詞＋である／なだけに / い形容詞＋だけに / 名詞（＋である／な）＋だけに"},"examples":[{"ja":"駅が近いだけに家賃も高い。","en":"Precisely because it's close to the station, the rent is high.","ko":"역이 가까운 만큼 집세도 비싸다."}],"similar":[]},
  {"id":"d1725293495850","pattern":"〜だけの","core":"だけの","blankTarget":"だけの","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"何かをするために必要な物の量や能力の程度を表します。 「動詞Ａだけの名詞Ｂ」で「Ａをするために必要なＢ」という意味になります。","en":"enough to...; sufficient for...","ko":"…할 만한; …할 정도의"},"formation":{"ja":"動詞辞書形＋だけの＋名詞","en":"動詞辞書形＋だけの＋名詞","ko":"動詞辞書形＋だけの＋名詞"},"examples":[{"ja":"彼女のわがままを全て聞いてあげるだけの包容力は私にはない。","en":"I don't have the tolerance to put up with all her selfishness.","ko":"그녀의 변덕을 전부 들어줄 만한 포용력은 내게 없다."}],"similar":[]},
  {"id":"d1725293495851","pattern":"〜だけのことだ","core":"だけのことだ","blankTarget":"だけのこと","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの用法があります。 ①事態を解決・打開する方法が一つだけあること ”それをすれば事態は容易に解決できるから大したことではない”というような、話者の楽観的な感情を表せるのが特徴です。 似ている文法に「【Ｎ３文法】～しかない」がありますが、こちらは他の方法や選択肢がなく、それをやる以外に方法がないこと（絶体絶命）を表します。多くは悲観的なニュアンスが含まれます。 ②強調 それ以上でもそれ以下でもないことを表します。","en":"all one has to do is...; that's all there is to it","ko":"…하면 그만이다; …에 지나지 않는다"},"formation":{"ja":"①動詞辞書形＋だけのことだ / 動ば形＋いいだけのことだ / ②名詞修飾形＋だけのことだ","en":"①動詞辞書形＋だけのことだ / 動ば形＋いいだけのことだ / ②名詞修飾形＋だけのことだ","ko":"①動詞辞書形＋だけのことだ / 動ば形＋いいだけのことだ / ②名詞修飾形＋だけのことだ"},"examples":[{"ja":"無知は罪ではない。知らないのであれば知ればいいだけのことだ。","en":"Ignorance is not a sin. If you don't know, you just have to learn.","ko":"무지는 죄가 아니다. 모르면 알면 그만이다."}],"similar":[]},
  {"id":"d1725293495852","pattern":"〜だけのことはある／だけある／だけあって／だけに(称賛)","core":"だけのことはある","blankTarget":"だけあって","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"理由の「から」や「ので」に言い換えることができますが、それらよりも前項の理由を強調する言い方として用いられ、「さすが～だから」「～にふさわしい程度」という意味を表します。 後項では身分や地位、経歴などに基づく主観的な評価が述べられます。多くの場合、褒め称える内容がきます。 「だけある」「だけのことはある」は文末に使われ、「さすが」「やっぱり」等がよく呼応します。 「だけあって」「だけに」は文中で用いられます。","en":"no wonder; as befits; lives up to","ko":"…답다; …인 만큼 대단하다; 과연 …답다"},"formation":{"ja":"動詞普通形＋だけあって／だけに／だけある／だけのことはある / な形容詞＋な＋だけあって／だけに／だけある／だけのことはある / い形容詞＋だけあって／だけに／だけある／だけのことはある / 名詞＋な＋だけあって／だけに／だけある／だけのことはある","en":"動詞普通形＋だけあって／だけに／だけある／だけのことはある / な形容詞＋な＋だけあって／だけに／だけある／だけのことはある / い形容詞＋だけあって／だけに／だけある／だけのことはある / 名詞＋な＋だけあって／だけに／だけある／だけのことはある","ko":"動詞普通形＋だけあって／だけに／だけある／だけのことはある / な形容詞＋な＋だけあって／だけに／だけある／だけのことはある / い形容詞＋だけあって／だけに／だけある／だけのことはある / 名詞＋な＋だけあって／だけに／だけある／だけのことはある"},"examples":[{"ja":"ダンス経験者なだけあって動きが他と違う。","en":"As befits someone with dance experience, their movements stand out from the rest.","ko":"댄스 경험자답게 움직임이 남다르다."}],"similar":[]},
  {"id":"d1725293495965","pattern":"〜たて／たての","core":"たて","blankTarget":"たて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"動ます形に接続して、「～たばかり」と同じ意味を表します。 特に新鮮な状態や新しい状態であることを表すので、良い意味だけに使えます。 なお、「～たて」は名詞として扱います。","en":"freshly...; just...","ko":"갓 …한; …한 지 얼마 안 된"},"formation":{"ja":"動ます形＋たて","en":"動ます形＋たて","ko":"動ます形＋たて"},"examples":[{"ja":"できたての料理は一番おいしい。","en":"Freshly made food tastes best.","ko":"갓 만든 요리가 가장 맛있다."}],"similar":[]},
  {"id":"d1725293495966","pattern":"〜たところ／たところが","core":"たところ","blankTarget":"たところが","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"逆接を表します。 後件には予想や期待に反した内容が述べられます。 例えば「お店に行ったところ、休みだった」では、話者はお店は休みではないと思っていたが、予想に反して休みだったというニュアンスが生まれます。予想とは反するところに逆接があります。 現在「～たところが」を使うことは非常に少なくなっていますが、「が」を省略した「～たところ」は一般的に用いられています。例文（１） また、「ところが」は接続詞として単独で用いることもできます。 これらと同じ表現に例文（４）の「～のに」があります。","en":"but; however; to one's surprise","ko":"…했더니 (예상과 달리); …였는데"},"formation":{"ja":"動た形＋ところ（が）","en":"動た形＋ところ（が）","ko":"動た形＋ところ（が）"},"examples":[{"ja":"彼なら知っていると思って聞いたところが、彼も知らなかった。","en":"I asked him thinking he would know, but he didn't know either.","ko":"그라면 알 거라고 생각하고 물어봤더니 그도 몰랐다."}],"similar":[]},
  {"id":"d1725293495963","pattern":"〜たまま／たままに／たままを","core":"たまま","blankTarget":"たままを","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"物事に何も手を加えない状態を表します。 この文型は知覚・感覚に関する動詞につき、「見たまま」「感じたまま」「聞いたまま」などの言い方に限られています。","en":"just as one saw/felt/heard; exactly as it is","ko":"…한 그대로; …한 대로"},"formation":{"ja":"動た形＋まま","en":"動た形＋まま","ko":"動た形＋まま"},"examples":[{"ja":"本物と同じような見たままを描く絵なら、写真でも良いでしょう。","en":"If it's a picture that depicts exactly what you see, a photograph would do just as well.","ko":"실물과 똑같이 보이는 그대로를 그리는 그림이라면 사진이어도 되겠지."}],"similar":[]},
  {"id":"d1725293495964","pattern":"〜たものだ","core":"たものだ","blankTarget":"だものだ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"過去のことを思い出して感慨深く感じる様子を表します。思い出に浸ったり、懐かしく思うような感じを強く表せます。 口語では「～たもんだ」となります。","en":"used to...; how ... it was (nostalgic recollection)","ko":"…하곤 했다; …했었다 (회상)"},"formation":{"ja":"動た形＋ものだ","en":"動た形＋ものだ","ko":"動た形＋ものだ"},"examples":[{"ja":"子どもの頃はよく川で泳いだものだ。","en":"I used to swim in the river a lot when I was a child.","ko":"어릴 때는 강에서 자주 수영하곤 했다."}],"similar":[]},
  {"id":"d1725293495968","pattern":"〜た途端に(とたん)","core":"た途端に(とたん)","blankTarget":"た途端","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件の動作後すぐに後件が発生したことを表します。過去のことにしか使えません。 後件は主語の身の回りで発生したこと、つまり主語自身が発見したことだけきます。したがって通常は話者にとって予想外だったことが述べられます。 後件は良いことでも悪いことでもいいです。 人称制限があり、二人称は主語になることはできません。","en":"the moment...; as soon as...","ko":"…하자마자; …하는 순간"},"formation":{"ja":"動た形＋途端（に）","en":"動た形＋途端（に）","ko":"動た形＋途端（に）"},"examples":[{"ja":"トイレ来た途端腹痛がおさまった。","en":"The moment I went into the bathroom, my stomachache subsided.","ko":"화장실에 들어가자마자 복통이 가라앉았다."}],"similar":[]},
  {"id":"d1753624948323","pattern":"〜つく","core":"つく","blankTarget":"つく","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「ギラつく（ギラギラ）」「モタつく（モタモタ）」「イラつく（イライラ）」などのようにオノマトペの語頭２拍に「～つく」をつけると、オノマトペが表す動作をする状態を表します。例えば「イライラ」から「イラつく」を作った場合、イライラしている状態（怒っている状態）を表します。 この「～つく」は様々なオノマトペにつくので造語力は比較的高いです。「～つく」をつけると五段動詞になります。","en":"to show a ... state; to act in a ... manner (from onomatopoeia)","ko":"…한 상태를 드러내다; …거리다"},"formation":{"ja":"オノマトペの語頭２拍＋つく","en":"オノマトペの語頭２拍＋つく","ko":"オノマトペの語頭２拍＋つく"},"examples":[{"ja":"夏の太陽がギラつく。","en":"The summer sun blazes.","ko":"여름 태양이 이글거린다."}],"similar":[]},
  {"id":"d1725293495895","pattern":"〜っこない","core":"っこない","blankTarget":"っこない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"物事が発生する可能性を強く否定する表現です。 この表現は「～はずがない」「～わけがない」の口語にあたります。 「どうせ」「なんて」などとよく呼応します。","en":"there's no way; not a chance","ko":"…할 리가 없다; 절대 …할 수 없다"},"formation":{"ja":"動ます形＋っこない","en":"動ます形＋っこない","ko":"動ます形＋っこない"},"examples":[{"ja":"人生はやり直しできっこないんだから、前を見るしかない。","en":"You can't redo life, so you have no choice but to look ahead.","ko":"인생은 다시 할 수 없으니 앞을 볼 수밖에 없다."}],"similar":[]},
  {"id":"d1725293495996","pattern":"〜つつ／つつも","core":"つつ","blankTarget":"つつも","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"相反する動作や性質が同時に存在することを述べる逆接の文法です。","en":"although; even while; while (contrasting two simultaneous facts)","ko":"…하면서도; …이면서도 (상반된 두 가지가 동시에 존재함)"},"formation":{"ja":"動ます形＋つつ（も）","en":"動ます形＋つつ（も）","ko":"動ます形＋つつ（も）"},"examples":[{"ja":"姪は小さい頃の面影を残しつつも、大人っぽい面もある。","en":"My niece still has traces of her childhood face, and yet she also has a grown-up side.","ko":"조카는 어릴 때의 모습을 간직하고 있으면서도 어른스러운 면도 있다."}],"similar":[]},
  {"id":"d1725293495955","pattern":"〜っぽい","core":"っぽい","blankTarget":"っぽい","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～の感じがする」「～の傾向がある」という意味を表します。普通はマイナスのイメージを持っている対象に対して使います。 「イ形容詞語幹＋っぽい」に接続できるイ形容詞は、「安っぽい」などかなり限定的です。 （１） あの服は安い （客観的） （２） あの服は安っぽい（主観的＋悪い印象） 「っぽい」を使うとあまり良い印象を持っていないことを表します。「安っぽい」というと、安くて悪いものだというような意味です。 「騙されたっぽい」「遅れたっぽい」「寂しがっているっぽい」など、動詞普通形にも接続できます。 このとき推測の「ようだ」、伝聞の「そうだ」とほぼ同じ意味になります。 「っぽい」自体はイ形容詞の活用が適用されます。","en":"seems like; -ish; tends to; easily does (often with a negative impression)","ko":"…같다; …스럽다; …하는 경향이 있다; 쉽게 …한다"},"formation":{"ja":"名詞＋っぽい / 動ます形＋っぽい / イ形容詞語幹＋っぽい / 動詞普通形＋っぽい","en":"名詞＋っぽい / 動ます形＋っぽい / イ形容詞語幹＋っぽい / 動詞普通形＋っぽい","ko":"名詞＋っぽい / 動ます形＋っぽい / イ形容詞語幹＋っぽい / 動詞普通形＋っぽい"},"examples":[{"ja":"彼は子供っぽい顔をしている。","en":"He has a childish face.","ko":"그는 아이 같은 얼굴을 하고 있다."}],"similar":[]},
  {"id":"d1725293495994","pattern":"〜つもりだ","core":"つもりだ","blankTarget":"つもり","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①事実とは異なる状態 二人称か三人称の主語をとり、その人が思っていることと、周囲が思っていることが異なることを表します。 ②自分の認識 物事に対する自分自身の客観的な認識を述べます。他の人がどう思っているかや、事実とは異なる内容だとしても関係なく使うことができます。この用法の時は必ず一人称の主語しかとりません。","en":"intend to; be convinced that (contrary to fact); consider oneself to be","ko":"…할 생각이다; …라고 생각하고 있다; …인 셈 치고 있다"},"formation":{"ja":"名詞＋のつもりだ / な形容詞＋なつもりだ / い形容詞＋つもりだ / 動た形＋つもりだ / 動ている形＋つもりだ","en":"名詞＋のつもりだ / な形容詞＋なつもりだ / い形容詞＋つもりだ / 動た形＋つもりだ / 動ている形＋つもりだ","ko":"名詞＋のつもりだ / な形容詞＋なつもりだ / い形容詞＋つもりだ / 動た形＋つもりだ / 動ている形＋つもりだ"},"examples":[{"ja":"なんだあの態度は。自分が王様にでもなったつもりか。","en":"What's with that attitude? Do you think you're a king or something?","ko":"저게 무슨 태도야. 자기가 왕이라도 된 줄 아는 건가."}],"similar":[]},
  {"id":"d1725293495995","pattern":"〜つもりで","core":"つもりで","blankTarget":"つもりで","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"強い意志や決意を持ちながら何かをすることを表します。","en":"with the intention of; resolved to; prepared to","ko":"…할 생각으로; …할 각오로"},"formation":{"ja":"動詞辞書形＋つもりで / 動ない形＋つもりで","en":"動詞辞書形＋つもりで / 動ない形＋つもりで","ko":"動詞辞書形＋つもりで / 動ない形＋つもりで"},"examples":[{"ja":"夏休みの宿題１日で終わらせるつもりでいたが、その決意はすぐに打ち砕かれた。","en":"I meant to finish my summer homework in a single day, but that resolve was quickly shattered.","ko":"여름방학 숙제를 하루 만에 끝낼 생각이었지만, 그 결심은 금방 무너졌다."}],"similar":[]},
  {"id":"d1725293495855","pattern":"〜である〜／〜の〜","core":"である〜","blankTarget":"である","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「友人の高橋さん」「社長の田中さん」などのように、上位語と下位語の用法の「の」は「である」に置き換えることができます。 「である」の前件と後件は同一物、同一人物を表し、後件の名詞は広く一般的に用いられる語がくることが多いです。 「である」は「の」よりも正式な場面で用いられます。","en":"who is; that is (apposition; more formal than の)","ko":"…인 (동격을 나타내며 'の'보다 격식적인 표현)"},"formation":{"ja":"名詞＋である＋名詞 / 名詞＋の＋名詞","en":"名詞＋である＋名詞 / 名詞＋の＋名詞","ko":"名詞＋である＋名詞 / 名詞＋の＋名詞"},"examples":[{"ja":"小学校の時の先生である蓮田先生に久しぶりに会った。","en":"I met Mr. Haseda, my elementary school teacher, for the first time in a long while.","ko":"초등학교 때 선생님이었던 하세다 선생님을 오랜만에 만났다."}],"similar":[]},
  {"id":"d1725293495971","pattern":"〜ていたところだ／〜ところに〜／〜ところへ〜","core":"ていたところだ","blankTarget":"ていたところ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある状態の継続中に、物事を進展させたり、事態が一変するような出来事が発生したことを表す文型です。","en":"just when ...; at the very moment ...; right in the middle of","ko":"마침 …하던 참이다; …하던 바로 그때에"},"formation":{"ja":"動ていた形＋ところだ / 動た形＋ところに／ところへ～ / 動ている形＋ところに／ところへ～","en":"動ていた形＋ところだ / 動た形＋ところに／ところへ～ / 動ている形＋ところに／ところへ～","ko":"動ていた形＋ところだ / 動た形＋ところに／ところへ～ / 動ている形＋ところに／ところへ～"},"examples":[{"ja":"友人から電話が来た。私もちょうど電話をかけようとしていたところだ。","en":"A friend called me. I was just about to make a call myself.","ko":"친구에게서 전화가 왔다. 마침 나도 전화를 걸려던 참이었다."}],"similar":[]},
  {"id":"d1725293495972","pattern":"〜てからでないと／てからでなければ","core":"てからでないと","blankTarget":"てからでないと","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項の条件が達成されないと物事の実現が不可能であること、あるいは何か良くない事態が生じることを表します。このとき、前項は後項の前提条件となります。 後項では、多くは良くない内容が述べられます。 口語では「～てからじゃないと」です。","en":"not until ...; unless ... first, (one cannot / something bad happens)","ko":"…하고 나서야; …한 다음이 아니면 (…할 수 없다)"},"formation":{"ja":"動て形＋てからでないと / 動て形＋てからでなければ","en":"動て形＋てからでないと / 動て形＋てからでなければ","ko":"動て形＋てからでないと / 動て形＋てからでなければ"},"examples":[{"ja":"まずはやってみてからでないと、できるかできないかは分からない。","en":"You won't know whether you can do it until you try it first.","ko":"우선 해 보고 나서야 할 수 있을지 없을지 알 수 있다."}],"similar":[]},
  {"id":"d1725293495857","pattern":"〜でしかない","core":"でしかない","blankTarget":"でしかない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"強調の文型で「～だ」と同じ意味です。 通常は名詞について、その名詞に対する低い評価のニュアンスが含まれます。 このとき悪い意味で使います。例文（１）～（４）。 形容詞性名詞につくとただ強調するだけで、その名詞に対する低い評価のニュアンスはありません。 この場合は良い意味でも悪い意味でも使えます。例文（５）～（12）。","en":"is nothing but; is merely; is just","ko":"…에 지나지 않는다; 그저 …일 뿐이다"},"formation":{"ja":"名詞＋でしかない / ナ形容詞語幹＋でしかない","en":"名詞＋でしかない / ナ形容詞語幹＋でしかない","ko":"名詞＋でしかない / ナ形容詞語幹＋でしかない"},"examples":[{"ja":"「時間がなくてできなかった」なんて言い訳でしかない。","en":"\"I didn't have time\" is nothing but an excuse.","ko":"'시간이 없어서 못 했다'는 건 변명에 지나지 않는다."}],"similar":[]},
  {"id":"d1725293495976","pattern":"〜てしまいそうだ","core":"てしまいそうだ","blankTarget":"てしまいそう","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"意志動詞に接続する場合と無意志動詞に接続する場合ではニュアンスが異なります。 ①意志動詞のテ形に接続する場合 自分の意志に反してその動作を行う可能性が高まっていることを表します。自身の欲求や誘惑、脅迫などで自制できなくなるニュアンスがあり、多くの場合は自身の行為に対して用います。 ②無意志動詞のテ形に接続する場合 条件・状況から見てそうなる可能性が高い、あるいは高まっていることを表します。 「～てしまう」が含まれていますが、良い事にも悪い事にも用いることができます。","en":"might end up ...ing; looks like (something unintended) will happen","ko":"…해 버릴 것 같다; …하게 될 것 같다"},"formation":{"ja":"動て形＋しまいそうだ","en":"動て形＋しまいそうだ","ko":"動て形＋しまいそうだ"},"examples":[{"ja":"このままでは三度寝してしまいそう。","en":"At this rate, I might end up dozing off again.","ko":"이대로라면 또 잠들어 버릴 것 같다."}],"similar":[]},
  {"id":"d1725293495975","pattern":"〜ての〜","core":"ての〜","blankTarget":"ての","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①手段や方法を表す 後件の名詞が表す動作を行う際の手段や方法を表します。 副詞的に用います。 ②動作の順序 前件の動作が終わった後に、後件の動作を行うことを表します。","en":"by means of ...ing; after doing (modifies a noun)","ko":"…하는 (수단·방법)의; …한 뒤의"},"formation":{"ja":"動て形＋の＋名詞","en":"動て形＋の＋名詞","ko":"動て形＋の＋名詞"},"examples":[{"ja":"ギターを抱えての移動は何かと不便だ。","en":"Getting around while carrying a guitar is inconvenient in all sorts of ways.","ko":"기타를 안고 이동하는 것은 여러모로 불편하다."}],"similar":[]},
  {"id":"d1725293495970","pattern":"〜てはいられない／てもいられない／てばかりはいられない／てばかりもいられない","core":"てはいられない","blankTarget":"てはいられない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"状況が緊迫しているため、以前の状態の継続が困難であることを表します。話者の現状に対する強い不安や焦燥感、更にその現状を変えようとする意志も感じられる文型です。 その状態を保つ意味を表す文法「～でいる」が元になっています。例文（６）。 ・子どものままでいたい。 ・誰も子どものままではいられない。 「居ても立ってもいられない（坐立不安／坐卧不宁）」は慣用表現です。","en":"can't afford to be ...ing; there's no time to keep ...ing; can't just keep ...ing","ko":"…하고 있을 때가 아니다; 계속 …하고만 있을 수 없다"},"formation":{"ja":"動て形＋てはいられない / 動て形＋てもいられない / 動て形＋ばかりはいられない / 動て形＋ばかりもいられない","en":"動て形＋てはいられない / 動て形＋てもいられない / 動て形＋ばかりはいられない / 動て形＋ばかりもいられない","ko":"動て形＋てはいられない / 動て形＋てもいられない / 動て形＋ばかりはいられない / 動て形＋ばかりもいられない"},"examples":[{"ja":"こうしてはいられない。早く行こう。","en":"I can't sit around like this. Let's go, and quickly.","ko":"이렇게 있고 있을 때가 아니다. 빨리 가자."}],"similar":[]},
  {"id":"d1725293495973","pattern":"〜ても〜ても(〜ない)","core":"ても〜ても(〜ない)","blankTarget":"ても","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ動詞のテ形を２回繰り返して接続します。その動作を何度行っても目標が達成されないことを表します。多くの場合は後件に否定形が呼応しますが、稀に肯定形が来る場合もあります。","en":"no matter how much one ...s; however often one ...s (still not)","ko":"아무리 …해도 …해도; …해도 …해도 (되지 않는다)"},"formation":{"ja":"動て形＋も＋動て形＋も～ない","en":"動て形＋も＋動て形＋も～ない","ko":"動て形＋も＋動て形＋も～ない"},"examples":[{"ja":"逃げても逃げても追いかけてくる。","en":"No matter how far you run, they keep chasing you.","ko":"도망쳐도 도망쳐도 계속 쫓아온다."}],"similar":[]},
  {"id":"d1725293495856","pattern":"〜でもしたら","core":"でもしたら","blankTarget":"でもしたら","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"仮定条件の文法です。 もし前件の事態が発生してしまったら、何か悪いことが発生することを表します。 後件は常に予想される良くない出来事が述べられます。","en":"if (someone) were to ...; if ... should happen (something bad follows)","ko":"…라도 하면; …라도 하게 되면 (좋지 않은 일이 생긴다)"},"formation":{"ja":"動ます形＋（なんか）でもしたら / 名詞＋（なんか）でもしたら","en":"動ます形＋（なんか）でもしたら / 名詞＋（なんか）でもしたら","ko":"動ます形＋（なんか）でもしたら / 名詞＋（なんか）でもしたら"},"examples":[{"ja":"大切なものを奪われでもしたら、私は死ぬ気で奪い返す。","en":"If anyone took something precious from me, I would get it back with everything I've got.","ko":"소중한 것을 빼앗기기라도 하면, 나는 죽을 각오로 되찾을 것이다."}],"similar":[]},
  {"id":"d1725293495974","pattern":"〜てもやむを得ない／やむを得ない","core":"てもやむを得ない","blankTarget":"てもやむを得ない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"そうなってしまうのは必然的でしょうがないことを表します。 単独で用いることもできます。例文（５）～（８）。","en":"it can't be helped even if ...; it is only natural that ...; unavoidable","ko":"…해도 어쩔 수 없다; …하는 것도 무리가 아니다; 어쩔 수 없다"},"formation":{"ja":"動て形＋もやむを得ない / 名詞＋でもやむを得ない / イ形語幹＋くてもやむを得ない / ナ形語幹＋でもやむを得ない / （単独）やむを得ない","en":"動て形＋もやむを得ない / 名詞＋でもやむを得ない / イ形語幹＋くてもやむを得ない / ナ形語幹＋でもやむを得ない / （単独）やむを得ない","ko":"動て形＋もやむを得ない / 名詞＋でもやむを得ない / イ形語幹＋くてもやむを得ない / ナ形語幹＋でもやむを得ない / （単独）やむを得ない"},"examples":[{"ja":"転職回数が多いと、企業の採用担当から「この人、せっかく採用してもすぐ辞めてしまうんじゃないか？」と疑念を持たれてもやむを得ない。","en":"If you change jobs often, it's only natural for hiring managers to wonder, \"Won't this person quit soon after we hire them?\"","ko":"이직 횟수가 많으면 기업 인사담당자가 '이 사람, 애써 뽑아도 곧 그만두지 않을까?' 하고 의심하는 것도 어쩔 수 없다."}],"similar":[]},
  {"id":"d1725293495990","pattern":"〜と〜ない","core":"と〜ない","blankTarget":"と","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"期間や数量を表す語について、それに少しも満たないことを表します。","en":"less than; not even (a given period or quantity)","ko":"…도 안 되어; …이 채 안 되어"},"formation":{"ja":"数量詞＋と～ない","en":"数量詞＋と～ない","ko":"数量詞＋と～ない"},"examples":[{"ja":"配属されて１週間と経たず辞めてしまった。","en":"He quit less than a week after being assigned to the post.","ko":"배속된 지 일주일도 안 되어 그만두었다."}],"similar":[]},
  {"id":"d1725293495979","pattern":"〜という","core":"という","blankTarget":"という","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"同じ名詞を２度繰り返して使い、「全ての～」の意味を表します。 全てのものを指し、例外を許しません。","en":"every single ...; all ... without exception","ko":"모든 …; …라는 …마다 (예외 없이 전부)"},"formation":{"ja":"名詞Ａ＋という＋名詞Ａ","en":"名詞Ａ＋という＋名詞Ａ","ko":"名詞Ａ＋という＋名詞Ａ"},"examples":[{"ja":"深夜で寝惚けていたからか、壁という壁にぶつかりながらトイレに行った。","en":"Perhaps because it was late at night and I was half-asleep, I bumped into wall after wall on my way to the bathroom.","ko":"한밤중이라 비몽사몽해서인지, 화장실에 가는 길에 벽이라는 벽은 다 부딪혔다."}],"similar":[]},
  {"id":"d1725293495980","pattern":"〜というものだ／ってもんだ","core":"というものだ","blankTarget":"というものだ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"事実、物事の本質や特徴など評価したり、断定的に述べたり、それについて説明を行うときに用います。 口語形は「というもんだ」「っていうものだ」「っていうもんだ」「ってもんだ」などがあります。","en":"that's what ... really is; that is the essence of ...; that's what you call ...","ko":"…라는 것이다; 그야말로 …인 것이다; …란 이런 것이다"},"formation":{"ja":"動詞普通形＋というものだ / イ形容詞普通形＋というものだ / ナ形容詞語幹＋というものだ / 名詞＋というものだ","en":"動詞普通形＋というものだ / イ形容詞普通形＋というものだ / ナ形容詞語幹＋というものだ / 名詞＋というものだ","ko":"動詞普通形＋というものだ / イ形容詞普通形＋というものだ / ナ形容詞語幹＋というものだ / 名詞＋というものだ"},"examples":[{"ja":"何でも話し合える、それが友達というものだ。","en":"Being able to talk about anything—that's what being friends is all about.","ko":"무엇이든 이야기할 수 있다는 것, 그것이 바로 친구라는 것이다."}],"similar":[]},
  {"id":"d1725293495981","pattern":"〜というものではない／というものでもない","core":"というものではない","blankTarget":"というものでもない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話者の主観的な意見や考え方を述べ、ある物事について全面的に否定する文型です。 「～というものでもない」はやや婉曲的な否定表現です。「～というものではない」は直接的な否定表現のため語気が強いです。 前件には「ただ」が呼応することがあります。 口語形は「っていうもんじゃない」「ってもんじゃない」です。 相手の安直な考え方を否定する場合には「（ただ）～ばいいというものではない」の文型がよく用いられます。 例文（１）（２）（３）（７）。","en":"is not necessarily; it is not that ...; ... is not always the case","ko":"…라고 할 수는 없다; 반드시 …인 것은 아니다"},"formation":{"ja":"文の普通形＋というものではない / 文の普通形＋というものでもない","en":"文の普通形＋というものではない / 文の普通形＋というものでもない","ko":"文の普通形＋というものではない / 文の普通形＋というものでもない"},"examples":[{"ja":"個性は強ければいいというものでもない。","en":"Having a strong personality isn't necessarily a good thing.","ko":"개성이 강하면 좋은 것만은 아니다."}],"similar":[]},
  {"id":"d1725293495982","pattern":"〜というより／〜というよりむしろ","core":"というより","blankTarget":"というより","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"二つの判断や見方を比較し、後件の方が比較的妥当であることを表します。 「むしろ」は省略可能ですが、「むしろ」がつくとより強調された表現となります。 「というより」「というよりは」「というよりか」「というよりも」「というよりかは」などと様々な言い方がありますが全て同じ意味です。","en":"rather than; more like; not so much ... as ...","ko":"…라기보다는; 오히려 …쪽이다"},"formation":{"ja":"名詞＋というよりむしろ～ / 動詞普通形＋というよりむしろ～ / い形容詞普通形＋というよりむしろ～ / な形容詞＋（だ／である）というよりむしろ","en":"名詞＋というよりむしろ～ / 動詞普通形＋というよりむしろ～ / い形容詞普通形＋というよりむしろ～ / な形容詞＋（だ／である）というよりむしろ","ko":"名詞＋というよりむしろ～ / 動詞普通形＋というよりむしろ～ / い形容詞普通形＋というよりむしろ～ / な形容詞＋（だ／である）というよりむしろ"},"examples":[{"ja":"声が聞こえないのはマイクが壊れているというより、パソコンの設定の方の問題だと思う。","en":"I think not being able to hear the sound is less a matter of the microphone being broken than a problem with the computer settings.","ko":"소리가 들리지 않는 것은 마이크가 고장 난 것이라기보다 컴퓨터 설정 문제인 것 같다."}],"similar":[]},
  {"id":"d1725293495983","pattern":"〜といわず／と言わず","core":"といわず","blankTarget":"と言わず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件を否定して、前件よりも高い程度や多い数量を求めることを表します。後件では欲求、願望、勧誘、提案などが来ます。","en":"not just ...; not stopping at ... (but even more)","ko":"…라고 하지 말고; …에 그치지 말고 (더 나아가)"},"formation":{"ja":"名詞＋と言わず","en":"名詞＋と言わず","ko":"名詞＋と言わず"},"examples":[{"ja":"今年のゴールデンウイークは１０連休らしいが、１０日と言わず１ヶ月くらい休みたい。","en":"They say this year's Golden Week is a ten-day holiday, but I'd like about a month off, not just ten days.","ko":"올해 황금연휴는 10일 연휴라고 하는데, 10일이라고 하지 말고 한 달쯤 쉬고 싶다."}],"similar":[]},
  {"id":"d1725293495984","pattern":"〜とかで","core":"とかで","blankTarget":"とかで","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"人づてに聞いた理由を表します。 話者の伝聞の内容に対する確証が低めなところが特徴です。 この文法における「とか」は伝聞を、「で」は理由・原因を表します。 「とか」は主に口語で用いられます。","en":"because (someone) said ...; reportedly because; on the grounds that ... or so","ko":"…라고 해서; …라는 이유로; …라는 말이 있어"},"formation":{"ja":"名詞＋（だ）とかで / な形容詞語幹＋（だ）とかで / い形容詞普通形＋とかで / 動詞普通形＋とかで","en":"名詞＋（だ）とかで / な形容詞語幹＋（だ）とかで / い形容詞普通形＋とかで / 動詞普通形＋とかで","ko":"名詞＋（だ）とかで / な形容詞語幹＋（だ）とかで / い形容詞普通形＋とかで / 動詞普通形＋とかで"},"examples":[{"ja":"彼風邪引いたとかで今日は欠席するらしい。","en":"He's apparently absent today because he caught a cold or something.","ko":"그는 감기에 걸렸다더니 오늘 결석하는 모양이다."}],"similar":[]},
  {"id":"d1725293495859","pattern":"〜どころか","core":"どころか","blankTarget":"どころか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話し手や聞き手が思い込んでいたこと、期待していたことが事実とは正反対であることを表します。","en":"far from; instead of; contrary to (expectation)","ko":"…은커녕; …는 고사하고 오히려"},"formation":{"ja":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか","en":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか","ko":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか"},"examples":[{"ja":"雨は弱まるどころか、ますます強くなってきた。","en":"Far from letting up, the rain has been getting heavier.","ko":"비는 잦아들기는커녕 점점 더 세지고 있다."}],"similar":[]},
  {"id":"d1725293495860","pattern":"〜どころか〜ない","core":"どころか〜ない","blankTarget":"どころか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"一般的に実現可能なことと思われていることができず、それだけでなくそれ以上に容易なこともできないことを表します。 前件よりも後件の方がより容易な内容がきます。 「～どころか～も～ない」「～どころか～さえも～ない」の形を取ることもあります。 例文（８）のように、「～だけでなく」と同じ使い方もできます。","en":"let alone; much less; (not only not ... but) not even ...","ko":"…은커녕 …조차 못 한다; …는 고사하고 …도 안 된다"},"formation":{"ja":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか","en":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか","ko":"名詞＋どころか / な形容詞語幹＋な／である＋どころか / い形容詞＋どころか / 動詞辞書形＋どころか"},"examples":[{"ja":"熱を出してしまい、ご飯を食べるどころか立ち上がることすらもできなくなった。","en":"I came down with a fever and couldn't even stand up, let alone eat.","ko":"열이나서 밥은커녕 일어나지도 못하게 되었다."}],"similar":[]},
  {"id":"d1725293495986","pattern":"〜ところだった","core":"ところだった","blankTarget":"ところだった","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"条件が異なれば発生していたであろう事態を、発生する前に回避することができたことを表します。 「もう少しで」や「危うく（あやうく）」などと呼応します。","en":"almost ...; nearly ...; was about to ... (but avoided it)","ko":"하마터면 …할 뻔했다; …할 뻔했다"},"formation":{"ja":"動詞辞書形＋ところだった / 動た形＋ところだった","en":"動詞辞書形＋ところだった / 動た形＋ところだった","ko":"動詞辞書形＋ところだった / 動た形＋ところだった"},"examples":[{"ja":"教えてくれなかったらまた忘れるところだった。","en":"If you hadn't told me, I would have forgotten again.","ko":"알려주지 않았더라면 또 잊어버릴 뻔했다."}],"similar":[]},
  {"id":"d1725293495858","pattern":"〜どころではない／どころの話ではない／どころの騒ぎではない","core":"どころではない","blankTarget":"どころではない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"意味が２つあります。 ①それをしている場合ではない 時間的・金銭的等の理由で事態が切迫しており、それをしている場合ではないことを表します。例文（１）～（４）。 ②事態はそれ以上である 「Ａどころではない」で、事態の程度はＡ以上であることを表します。良い事でも悪い事でも表すことができ、この用法でも事態が切迫しているニュアンスを持つこともあります。 例文（５）～（８）。 「それどころではない」「それどころではなく～」は慣用的に用いられる表現です。 「それどころではなく」は単独で接続詞的な使い方ができます。","en":"this is no time for ...; not a matter of ...; far beyond ...","ko":"…할 상황이 아니다; …은커녕; …와는 비교도 안 될 정도다"},"formation":{"ja":"動作性の名詞＋どころではない / 動詞辞書形＋どころではない / 動ている形＋どころではない","en":"動作性の名詞＋どころではない / 動詞辞書形＋どころではない / 動ている形＋どころではない","ko":"動作性の名詞＋どころではない / 動詞辞書形＋どころではない / 動ている形＋どころではない"},"examples":[{"ja":"年末だが何かと忙しくて大掃除どころではない。","en":"It's the end of the year, but I'm so busy with one thing and another that I have no time for the big cleanup.","ko":"연말인데 이것저것 바빠서 대청소는커녕 할 상황이 아니다."}],"similar":[]},
  {"id":"d1725293495987","pattern":"〜ところを","core":"ところを","blankTarget":"ところを","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"動作中を表します。 後件では「見る」「見つかる」「見つける」「発見する」などの語や、「捕まる」「逮捕する」「助ける」「呼び止める」など前件の動作を制止するような内容がきます。","en":"while ...ing; in the middle of ...ing (when someone intervenes)","ko":"…하던 중에; …하고 있는 것을"},"formation":{"ja":"動た形＋ところを / 動ている形＋ところを","en":"動た形＋ところを / 動ている形＋ところを","ko":"動た形＋ところを / 動ている形＋ところを"},"examples":[{"ja":"タバコを吸っているところを先生に見つかった。","en":"I was caught smoking by my teacher.","ko":"담배를 피우고 있는 것을 선생님에게 들켰다."}],"similar":[]},
  {"id":"d1725293495988","pattern":"〜ところを見ると","core":"ところを見ると","blankTarget":"ところを見ると","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"状況や様子から推測される物事を述べる文型です。 推測は話者の主観によるものです。","en":"judging from ...; seeing that ...","ko":"…하는 것을 보면; …한 걸 보면"},"formation":{"ja":"動詞普通形＋ところを見ると","en":"動詞普通形＋ところを見ると","ko":"動詞普通形＋ところを見ると"},"examples":[{"ja":"急に逃げ出したところを見ると、何かやましいことがあるのだろう。","en":"Judging from the way he suddenly ran off, he must have something to hide.","ko":"갑자기 도망친 것을 보면 뭔가 떳떳하지 못한 일이 있는 모양이다."}],"similar":[]},
  {"id":"d1725293495991","pattern":"〜としか言いようがない","core":"としか言いようがない","blankTarget":"としか言いようがない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"強調の表現です。","en":"there is no other way to put it; it can only be described as","ko":"…라고밖에 말할 수 없다; …라고 밖에 표현할 방법이 없다"},"formation":{"ja":"文の普通形＋としか言いようがない / な形容詞語幹（＋だ）＋としか言いようがない / 名詞（＋だ）＋としか言いようがない","en":"文の普通形＋としか言いようがない / な形容詞語幹（＋だ）＋としか言いようがない / 名詞（＋だ）＋としか言いようがない","ko":"文の普通形＋としか言いようがない / な形容詞語幹（＋だ）＋としか言いようがない / 名詞（＋だ）＋としか言いようがない"},"examples":[{"ja":"目の付け所は良いが、実現不可能としか言いようがない。","en":"The idea is good, but it can only be described as impossible to achieve.","ko":"착안점은 좋지만 실현 불가능하다고밖에 말할 수 없다."}],"similar":[]},
  {"id":"d1725293495993","pattern":"〜としては","core":"としては","blankTarget":"としては","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"人物や組織を表す語について、その立場にとってどうであるかを述べる文型です。 「～としましては」「～といたしましては」は謙譲語です。 「は」は省略不可能です。","en":"as (for); from the standpoint of; in one's capacity as","ko":"…로서는; …의 입장에서는"},"formation":{"ja":"名詞＋としては","en":"名詞＋としては","ko":"名詞＋としては"},"examples":[{"ja":"私個人としては到底納得できません。","en":"As an individual, I simply cannot accept it.","ko":"저 개인으로서는 도저히 납득할 수 없습니다."}],"similar":[]},
  {"id":"d1725293495977","pattern":"〜とは反対に／〜とは逆に","core":"とは反対に","blankTarget":"逆に","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"二つの物事を対比、比較対照させる文型です。 前項と後項が逆の状態であったり、あるいは期待される結果とは異なることを述べます。 「反対に」「逆に」「それとは反対に」「それとは逆に」は接続詞的に単独で用いることができます。","en":"contrary to; on the contrary; the opposite of","ko":"…와는 반대로; …와는 달리; 오히려"},"formation":{"ja":"動詞普通形＋とは反対に／逆に / い形容詞名詞修飾形＋とは反対に／逆に / な形容詞名詞修飾形＋とは反対に／逆に / 名詞＋とは反対に","en":"動詞普通形＋とは反対に／逆に / い形容詞名詞修飾形＋とは反対に／逆に / な形容詞名詞修飾形＋とは反対に／逆に / 名詞＋とは反対に","ko":"動詞普通形＋とは反対に／逆に / い形容詞名詞修飾形＋とは反対に／逆に / な形容詞名詞修飾形＋とは反対に／逆に / 名詞＋とは反対に"},"examples":[{"ja":"寝るために静かな音楽聞いていたのに、逆に聞き入って眠れなくなった。","en":"I was listening to quiet music to fall asleep, but instead I got absorbed in it and couldn't sleep.","ko":"잠들려고 조용한 음악을 듣고 있었는데, 오히려 음악에 빠져서 잠을 못 잤다."}],"similar":[]},
  {"id":"d1725293495989","pattern":"〜と見える／に見える／かに見える／かのように見える","core":"と見える","blankTarget":"かに見える","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"人や物事の外見を見て、それに対する自分の推測を述べる用法です。 その推測は主観的な判断によるものです。","en":"appears to be; looks as if; seems (based on outward appearance)","ko":"…처럼 보인다; …인 듯 보인다; …인 것처럼 보인다"},"formation":{"ja":"名詞＋（だ）と見える／（か）に見える／かのように見える / な形容詞語幹＋（だ）と見える／（か）に見える／かのように見える / 動詞普通形＋と見える／かに見える／（かの）ように見える / い形容詞＋と見える／かに見える／かのように見える","en":"名詞＋（だ）と見える／（か）に見える／かのように見える / な形容詞語幹＋（だ）と見える／（か）に見える／かのように見える / 動詞普通形＋と見える／かに見える／（かの）ように見える / い形容詞＋と見える／かに見える／かのように見える","ko":"名詞＋（だ）と見える／（か）に見える／かのように見える / な形容詞語幹＋（だ）と見える／（か）に見える／かのように見える / 動詞普通形＋と見える／かに見える／（かの）ように見える / い形容詞＋と見える／かに見える／かのように見える"},"examples":[{"ja":"ドルは下げ止まったかに見えるが、これからどうなるかは未知数だ。","en":"The dollar appears to have stopped falling, but what happens next is uncertain.","ko":"달러는 하락세가 멈춘 것처럼 보이지만 앞으로 어떻게 될지는 미지수다."}],"similar":[]},
  {"id":"d1725293495978","pattern":"〜と言っても過言ではない","core":"と言っても過言ではない","blankTarget":"と言っても過言ではない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"評価を述べる文型です。 そのような評価をしても差し支えないことを表します。 以下のようなバリエーションがあります。最も使われるのは「～と言っても過言ではない／と言ってもいい」です。 ～と言っても過言ではない ～と言っても言い過ぎではない ～と言っても間違いない ～と言ってもいい","en":"it is no exaggeration to say that ...","ko":"…라고 해도 과언이 아니다"},"formation":{"ja":"文＋と言っても過言ではない","en":"文＋と言っても過言ではない","ko":"文＋と言っても過言ではない"},"examples":[{"ja":"彼は私の命の恩人だと言っても過言ではない。","en":"It is no exaggeration to say that he saved my life.","ko":"그는 나의 생명의 은인이라고 해도 과언이 아니다."}],"similar":[]},
  {"id":"d1725293495918","pattern":"〜ないことには","core":"ないことには","blankTarget":"ないことには","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項は後項が成立する前提条件で、前項が成立しなければ、後項も成立しないことを表します。 後項は必ず否定形をとります。","en":"unless ...; without ... (one cannot)","ko":"…하지 않고서는; …하지 않으면 (…할 수 없다)"},"formation":{"ja":"動ない形＋ないことには / い形容詞ない形＋ないことには / な形容詞語幹＋で＋ないことには / 名詞＋で＋ないことには","en":"動ない形＋ないことには / い形容詞ない形＋ないことには / な形容詞語幹＋で＋ないことには / 名詞＋で＋ないことには","ko":"動ない形＋ないことには / い形容詞ない形＋ないことには / な形容詞語幹＋で＋ないことには / 名詞＋で＋ないことには"},"examples":[{"ja":"説明がないことには手が付けられない。","en":"Without an explanation, I can't even get started.","ko":"설명이 없으면 손도 댈 수 없다."}],"similar":[]},
  {"id":"d1725293495919","pattern":"〜なしでは〜ない／〜なしには〜ない／〜なしに〜ない","core":"なしでは〜ない","blankTarget":"なしでは","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件で述べられる条件が満たされなければ後件が成り立たないことを表します。 後項では必ず「～できない」「～ない」のような否定形、あるいは否定的な内容が呼応します。","en":"without ... (one cannot); if there is no ..., ... is impossible","ko":"…없이는 …할 수 없다; …없으면 안 된다"},"formation":{"ja":"名詞＋無しでは～ない / 名詞＋無しには～ない","en":"名詞＋無しでは～ない / 名詞＋無しには～ない","ko":"名詞＋無しでは～ない / 名詞＋無しには～ない"},"examples":[{"ja":"君なしでは生きていけない。","en":"I can't live without you.","ko":"너 없이는 살 수 없어."}],"similar":[]},
  {"id":"d1725293495920","pattern":"〜なしに／なしで／もなしに／もなしで","core":"なしに","blankTarget":"なしに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件の動作が行われないまま後件の動作が行われることを表す文型です。","en":"without ...ing; with no ...","ko":"…없이; …하지 않은 채"},"formation":{"ja":"名詞＋（も）なしに","en":"名詞＋（も）なしに","ko":"名詞＋（も）なしに"},"examples":[{"ja":"また同じようなことが行われるのであれば、今後は警告なしに対抗手段を講じます。","en":"If the same sort of thing happens again, I will take countermeasures without warning from now on.","ko":"또 비슷한 일이 일어난다면 앞으로는 경고 없이 대응 조치를 취하겠습니다."}],"similar":[]},
  {"id":"d1725293495917","pattern":"〜など〜ものか／〜なんか〜ものか／〜なんて〜ものか","core":"など〜ものか","blankTarget":"など","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"強い否定を表します。 話者の軽蔑・軽視・謙遜の感情を含みます。 「～などあろうものか（などあるものか）」は定型表現です。","en":"as if ... would; there's no way ...; how could there be ...","ko":"…할 리가 있겠는가; … 따위 있을 리 없다"},"formation":{"ja":"動詞普通形＋など＋動詞辞書形＋ものか / イ形容詞普通形＋など＋動詞辞書形＋ものか / ナ形容詞普通形＋など＋動詞辞書形＋ものか / 名詞＋など＋動詞辞書形＋ものか / 名詞＋など（＋助詞）＋動詞辞書形＋ものか","en":"動詞普通形＋など＋動詞辞書形＋ものか / イ形容詞普通形＋など＋動詞辞書形＋ものか / ナ形容詞普通形＋など＋動詞辞書形＋ものか / 名詞＋など＋動詞辞書形＋ものか / 名詞＋など（＋助詞）＋動詞辞書形＋ものか","ko":"動詞普通形＋など＋動詞辞書形＋ものか / イ形容詞普通形＋など＋動詞辞書形＋ものか / ナ形容詞普通形＋など＋動詞辞書形＋ものか / 名詞＋など＋動詞辞書形＋ものか / 名詞＋など（＋助詞）＋動詞辞書形＋ものか"},"examples":[{"ja":"自分で決めたことだ。後悔などあろうものか。","en":"It's something I decided myself. What regrets could there be?","ko":"내가 스스로 정한 일이다. 후회 따위 있을 리가 있겠나."}],"similar":[]},
  {"id":"d1725293495921","pattern":"〜にあたって／にあたり／にあたっての","core":"にあたって","blankTarget":"にあたっての","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"重要な時や段階であることを表します。 挨拶などに用いられることもあります。","en":"on the occasion of; when doing; in undertaking (formal)","ko":"…에 즈음하여; …할 때에; …에 앞서"},"formation":{"ja":"動詞辞書形＋にあたって／あたり / 名詞＋にあたって／あたり / ～にあたっての＋名詞","en":"動詞辞書形＋にあたって／あたり / 名詞＋にあたって／あたり / ～にあたっての＋名詞","ko":"動詞辞書形＋にあたって／あたり / 名詞＋にあたって／あたり / ～にあたっての＋名詞"},"examples":[{"ja":"（選手へのインタビューで）「今回の対戦にあたっての意気込みをお願いします。」","en":"(In an interview with a player) \"Please tell us how you feel going into this match.\"","ko":"(선수 인터뷰에서) \"이번 경기에 임하는 각오를 말씀해 주세요.\""}],"similar":[]},
  {"id":"d1725293495937","pattern":"〜において／においても／における","core":"において","blankTarget":"における","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"場所や時間帯・時代、範囲（方面、領域）を表します。 場所や時間帯・時代を表す場合は、「で」「での＋名詞」に置き換えられます。つまり「～において」は複合助詞です。 「～においては」と、強調の「は」が後続する場合もあります。 「何においても」「何事においても」などは慣用表現。 書き言葉です。","en":"in; at; regarding (a place, time, or field; formal)","ko":"…에 있어서; …에서; …에 관한 (격식체)"},"formation":{"ja":"名詞＋において（は） / 名詞＋においても / 名詞＋における＋名詞","en":"名詞＋において（は） / 名詞＋においても / 名詞＋における＋名詞","ko":"名詞＋において（は） / 名詞＋においても / 名詞＋における＋名詞"},"examples":[{"ja":"災害現場における初期対応の迅速さは人命に直結する。","en":"The speed of the initial response at a disaster site directly affects human lives.","ko":"재해 현장에서의 초기 대응 속도는 인명과 직결된다."}],"similar":[]},
  {"id":"d1725293495929","pattern":"〜にかかわらず／にかかわりなく","core":"にかかわらず","blankTarget":"にかかわらず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"名詞なら学歴、国籍、成績、理由、合否、成否など複数の側面がある単語と結び付き、動詞や形容詞なら肯定形と否定形を繰り返して接続し、前項の結果や状態に左右されずに後項の内容を行うことを表します。","en":"regardless of; irrespective of; whether ... or not","ko":"…에 관계없이; …와 상관없이; …이든 아니든"},"formation":{"ja":"名詞＋にかかわらず／かかわりなく / 動詞辞書形＋動ない形＋ないにかかわらず / い形容詞辞書形＋い形容詞ない形＋にかかわらず / な形容詞語幹＋な形容詞語幹＋でないにかかわらず / 名詞＋（の）あるなしにかかわらず","en":"名詞＋にかかわらず／かかわりなく / 動詞辞書形＋動ない形＋ないにかかわらず / い形容詞辞書形＋い形容詞ない形＋にかかわらず / な形容詞語幹＋な形容詞語幹＋でないにかかわらず / 名詞＋（の）あるなしにかかわらず","ko":"名詞＋にかかわらず／かかわりなく / 動詞辞書形＋動ない形＋ないにかかわらず / い形容詞辞書形＋い形容詞ない形＋にかかわらず / な形容詞語幹＋な形容詞語幹＋でないにかかわらず / 名詞＋（の）あるなしにかかわらず"},"examples":[{"ja":"自分よりも優れた部分がある人は、性別や年齢にかかわらず尊敬できる。","en":"Regardless of gender or age, I can respect people who have qualities superior to my own.","ko":"자신보다 뛰어난 부분이 있는 사람은 성별이나 나이에 관계없이 존경할 수 있다."}],"similar":[]},
  {"id":"d1725293495942","pattern":"〜にしたがって(従って)／にしたがい(従い)","core":"にしたがって(従って)","blankTarget":"に従い","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"規則、命令、指示、案内、人名や組織名などについて、それらを守りながら行動することを表します。","en":"in accordance with; following; obeying","ko":"…에 따라; …을 좇아; …에 따라서"},"formation":{"ja":"名詞＋に従って／に従い / 動詞辞書形＋に従って／に従い","en":"名詞＋に従って／に従い / 動詞辞書形＋に従って／に従い","ko":"名詞＋に従って／に従い / 動詞辞書形＋に従って／に従い"},"examples":[{"ja":"スタッフの案内に従い、入場していただきますようお願いいたします。","en":"Please follow the staff's instructions when entering.","ko":"스태프의 안내에 따라 입장해 주시기 바랍니다."}],"similar":[]},
  {"id":"d1725293495943","pattern":"〜にしたら／にすれば／にしても","core":"にしたら","blankTarget":"にしたら","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"人物を表す名詞について、その人物から見た考え方を推測して述べる文法です。 話者自身を表す語には原則接続できません。 似ている文型「【Ｎ１文法】～にしてみたら／にしてみれば／にしてみても」なら自分自身を表す語に接続できます。 ✕私にしたら ✕私にすれば ✕私にしても 〇私としては 〇私にとっては 〇私からみて 〇私にしてみれば","en":"from ...'s point of view; as far as ... is concerned; for ...","ko":"…의 입장에서 보면; …로서는; …에게는"},"formation":{"ja":"人物を表す名詞＋にしたら / 人物を表す名詞＋にすれば / 人物を表す名詞＋にしても","en":"人物を表す名詞＋にしたら / 人物を表す名詞＋にすれば / 人物を表す名詞＋にしても","ko":"人物を表す名詞＋にしたら / 人物を表す名詞＋にすれば / 人物を表す名詞＋にしても"},"examples":[{"ja":"彼女にしたら初めての子供だろうし、育児で悩むのもしょうがないことだ。","en":"For her it would be her first child, so it's no wonder she worries about parenting.","ko":"그녀 입장에서는 첫아이일 테니 육아로 고민하는 것도 어쩔 수 없는 일이다."}],"similar":[]},
  {"id":"d1725293495944","pattern":"〜にしては","core":"にしては","blankTarget":"にしては","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"一般的に想定される結果とは相反する結果が生じたこと、事実と想定されることが相反していることを表します。前件と後件の主語は同一でなければいけません。","en":"for; considering; by the standards of","ko":"…치고는; …에 비해서는"},"formation":{"ja":"動詞普通形＋にしては / い形容詞普通形＋にしては / な形容詞語幹＋にしては / 名詞＋にしては","en":"動詞普通形＋にしては / い形容詞普通形＋にしては / な形容詞語幹＋にしては / 名詞＋にしては","ko":"動詞普通形＋にしては / い形容詞普通形＋にしては / な形容詞語幹＋にしては / 名詞＋にしては"},"examples":[{"ja":"この子は、１５歳にしてはずいぶん大人っぽい。","en":"This child is quite mature for a fifteen-year-old.","ko":"이 아이는 열다섯 살치고는 꽤 어른스럽다."}],"similar":[]},
  {"id":"d1725293495941","pattern":"〜にしろ／〜にしたって／〜にせよ／〜にしても","core":"にしろ","blankTarget":"にせよ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"例外無く物事が成立することを表します。 「どんなに」「いくら」などが呼応します。","en":"whichever; whether ... or; even if; in any case","ko":"…든지; …라고 해도; 어찌 됐든"},"formation":{"ja":"動詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / い形容詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / な形容詞語幹（＋である）＋～にしろ／～にしたって／～にせよ／～にしても / 名詞（＋である）＋～にしろ／～にしたって／～にせよ／～にしても","en":"動詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / い形容詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / な形容詞語幹（＋である）＋～にしろ／～にしたって／～にせよ／～にしても / 名詞（＋である）＋～にしろ／～にしたって／～にせよ／～にしても","ko":"動詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / い形容詞普通形＋～にしろ／～にしたって／～にせよ／～にしても / な形容詞語幹（＋である）＋～にしろ／～にしたって／～にせよ／～にしても / 名詞（＋である）＋～にしろ／～にしたって／～にせよ／～にしても"},"examples":[{"ja":"何にせよまず安全第一である。","en":"Whatever the case, safety comes first.","ko":"어찌 됐든 우선 안전이 제일이다."}],"similar":[]},
  {"id":"d1725293495949","pattern":"〜につき","core":"につき","blankTarget":"につき","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～について」と同じ意味を持ちます。 「～について」よりも改まった表現です。","en":"regarding; concerning; on (formal)","ko":"…에 관해; …에 대하여 (격식체)"},"formation":{"ja":"名詞＋につき","en":"名詞＋につき","ko":"名詞＋につき"},"examples":[{"ja":"移転問題につき、野党からの激しい追及を受けている。","en":"He is facing fierce questioning from the opposition over the relocation issue.","ko":"이전 문제에 관해 야당의 거센 추궁을 받고 있다."}],"similar":[]},
  {"id":"d1725293495925","pattern":"〜にほかならない／ほかならぬ〜","core":"にほかならない","blankTarget":"にほかならない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"断定、強調の表現です。 他の選択肢はなく、まさにそれであることを表します。","en":"is nothing other than; is precisely; is none other than","ko":"…에 다름 아니다; 바로 …이다; …이야말로"},"formation":{"ja":"名詞＋にほかならない / ほかならぬ＋名詞","en":"名詞＋にほかならない / ほかならぬ＋名詞","ko":"名詞＋にほかならない / ほかならぬ＋名詞"},"examples":[{"ja":"人として最も大事なのは、心の強さにほかならない。","en":"What matters most as a human being is none other than strength of heart.","ko":"사람으로서 가장 중요한 것은 마음의 강인함에 다름 아니다."}],"similar":[]},
  {"id":"d1725293495933","pattern":"〜にまでなる","core":"にまでなる","blankTarget":"にまでなった","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある段階や状態に達することを表します。変化の過程を含意します。 良いことにも悪いことにも使えます。 「なる」以外の代わりに変化動詞「変わる」「変化する」「進歩する」「成長する」なども使えます。","en":"even become; reach the stage of being","ko":"심지어 ~이/가 되다; ~하는 단계에 이르다"},"formation":{"ja":"名詞＋にまでなる","en":"名詞＋にまでなる","ko":"名詞＋にまでなる"},"examples":[{"ja":"この廃墟は改装され、今では人気のホテルにまでなった。","en":"This ruin was renovated and has now even become a popular hotel.","ko":"이 폐허는 개조되어 지금은 인기 호텔이 되기까지 했다."}],"similar":[]},
  {"id":"d1725293495934","pattern":"〜にもかかわらず","core":"にもかかわらず","blankTarget":"にもかかわらず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"逆接の文型です。 後件には既に発生した予想外の事態が述べられます。 「にもかかわらず」「それにもかかわらず」は接続詞として単独で使えます。","en":"despite; in spite of; even though","ko":"~에도 불구하고; ~임에도"},"formation":{"ja":"名詞＋（である）にもかかわらず / な形容詞語幹＋（である）にもかかわらず / い形容詞普通形＋にもかかわらず / 動詞普通形＋にもかかわらず","en":"名詞＋（である）にもかかわらず / な形容詞語幹＋（である）にもかかわらず / い形容詞普通形＋にもかかわらず / 動詞普通形＋にもかかわらず","ko":"名詞＋（である）にもかかわらず / な形容詞語幹＋（である）にもかかわらず / い形容詞普通形＋にもかかわらず / 動詞普通形＋にもかかわらず"},"examples":[{"ja":"彼は勤務時間にもかかわらず漫画を読んでいる。","en":"Even though he is on working hours, he is reading manga.","ko":"그는 근무 시간임에도 불구하고 만화를 읽고 있다."}],"similar":[]},
  {"id":"d1725293495922","pattern":"〜に違いない","core":"に違いない","blankTarget":"に違いない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"何らかの根拠に基づく、話し手の強めの判断・断定を表します。","en":"must be; there is no doubt that","ko":"틀림없이 ~이다; 분명 ~이다"},"formation":{"ja":"動詞普通形＋に違いない / い形容詞普通形＋に違いない / な形容詞語幹＋に違いない / 名詞＋に違いない","en":"動詞普通形＋に違いない / い形容詞普通形＋に違いない / な形容詞語幹＋に違いない / 名詞＋に違いない","ko":"動詞普通形＋に違いない / い形容詞普通形＋に違いない / な形容詞語幹＋に違いない / 名詞＋に違いない"},"examples":[{"ja":"彼女の表情を見る限り、何か秘密があるに違いない。","en":"Judging by her expression, she must be hiding some secret.","ko":"그녀의 표정을 보아하건대 분명 무슨 비밀이 있을 것이다."}],"similar":[]},
  {"id":"d1725293495945","pattern":"〜に沿って／に沿った","core":"に沿って","blankTarget":"に沿って","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"意味は２つあります。 ①道路や河川、建造物の沿線上、あるいはそれまでの流れ ②状況や方針に応じること、あるいはマニュアル、説明書などの操作手順に従うこと","en":"along; in line with; in accordance with","ko":"~을 따라; ~에 맞추어; ~에 따라"},"formation":{"ja":"名詞＋に沿って / 名詞＋に沿った＋名詞","en":"名詞＋に沿って / 名詞＋に沿った＋名詞","ko":"名詞＋に沿って / 名詞＋に沿った＋名詞"},"examples":[{"ja":"運命に沿って生きる。","en":"To live in accordance with one's destiny.","ko":"운명을 따라 살다."}],"similar":[]},
  {"id":"d1725293495931","pattern":"〜に応えて／に応え","core":"に応えて","blankTarget":"に応えて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"他からの働きかけに対して反応することを表します。 主に期待、要望、要求、要請、意見などの語に接続します。 動詞「応える」も同様です。","en":"in response to; in answer to; to meet (expectations, requests)","ko":"~에 부응하여; ~에 응하여"},"formation":{"ja":"名詞＋に応えて","en":"名詞＋に応えて","ko":"名詞＋に応えて"},"examples":[{"ja":"今日は娘の誕生日なので、リクエストに応えてイタリアンを食べに行った。","en":"Today is my daughter's birthday, so we went out for Italian food as she requested.","ko":"오늘은 딸의 생일이라 요청에 응하여 이탈리아 음식을 먹으러 갔다."}],"similar":[]},
  {"id":"d1725293495938","pattern":"〜に応じて／に応じ／に応じた","core":"に応じて","blankTarget":"に応じて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件の条件に合わせて何かをすることを表す文型です。 動詞「応じる」は元々相手の行動に対応してこちらが行動を起こすことを表します。例文（９）（10）","en":"depending on; according to; in proportion to","ko":"~에 따라; ~에 상응하여"},"formation":{"ja":"名詞＋に応じ（て） / 名詞＋に応じた＋名詞","en":"名詞＋に応じ（て） / 名詞＋に応じた＋名詞","ko":"名詞＋に応じ（て） / 名詞＋に応じた＋名詞"},"examples":[{"ja":"買い物金額に応じてポイントが溜まり、次回以降１ポイント１円として使用できます。","en":"Points accumulate according to the purchase amount and can be used from the next purchase onward at one point per yen.","ko":"구매 금액에 따라 포인트가 쌓이고, 다음부터는 1포인트를 1엔으로 사용할 수 있습니다."}],"similar":[]},
  {"id":"d1725293495932","pattern":"〜に加えて／に加え","core":"に加えて","blankTarget":"に加え","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"累加（添加）の文型です。 「～に加えて、～も」の形で使われることが多いです。","en":"in addition to; on top of; besides","ko":"~에 더하여; ~에 추가로"},"formation":{"ja":"名詞＋に加えて","en":"名詞＋に加えて","ko":"名詞＋に加えて"},"examples":[{"ja":"目標を達成するには自分で行動する事に加え、他人のサポートも必要です。","en":"To achieve your goals, you need not only to take action yourself but also the support of others.","ko":"목표를 달성하려면 스스로 행동하는 것에 더해 다른 사람의 지원도 필요합니다."}],"similar":[]},
  {"id":"d1725293495947","pattern":"〜に過ぎない","core":"に過ぎない","blankTarget":"に過ぎません","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"非常に低い程度、「～でしかない」という意味を表し、取るに足らない、たいしたことはない、あまり重要ではないなどの軽視したニュアンスが含まれます。 「ほんの」「ただ」「ただの」「たった」「単なる」など呼応することがあります。","en":"merely; nothing more than; only","ko":"~에 불과하다; 단지 ~일 뿐이다"},"formation":{"ja":"動詞普通形＋に過ぎない / い形容詞普通形＋に過ぎない / な形容詞語幹＋である＋に過ぎない / 名詞（＋である）＋に過ぎない","en":"動詞普通形＋に過ぎない / い形容詞普通形＋に過ぎない / な形容詞語幹＋である＋に過ぎない / 名詞（＋である）＋に過ぎない","ko":"動詞普通形＋に過ぎない / い形容詞普通形＋に過ぎない / な形容詞語幹＋である＋に過ぎない / 名詞（＋である）＋に過ぎない"},"examples":[{"ja":"これはあくまで私一個人の意見に過ぎません。","en":"This is nothing more than my own personal opinion.","ko":"이것은 어디까지나 제 개인적인 의견에 불과합니다."}],"similar":[]},
  {"id":"d1725293495935","pattern":"〜に基づいて／に基づき／に基づく／に基づいた","core":"に基づいて","blankTarget":"に基づいて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"何らかを根拠にして述べる文法です。 「に基づいて／に基づき」は文中で、「に基づく／に基づいた」の後ろには名詞が接続されます。","en":"based on; on the basis of; grounded in","ko":"~에 근거하여; ~에 기초하여"},"formation":{"ja":"名詞＋に基づいて／に基づき / 名詞＋に基づく／に基づいた＋名詞","en":"名詞＋に基づいて／に基づき / 名詞＋に基づく／に基づいた＋名詞","ko":"名詞＋に基づいて／に基づき / 名詞＋に基づく／に基づいた＋名詞"},"examples":[{"ja":"コメンテーターなのに、発言が事実に基づいていない。","en":"Even though he is a commentator, his remarks are not based on facts.","ko":"코멘테이터인데도 발언이 사실에 근거하지 않는다."}],"similar":[]},
  {"id":"d1725293495930","pattern":"〜に決まっている","core":"に決まっている","blankTarget":"に決まっている","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話し手の自信に満ちた強めの判断・断定を表します。","en":"must be; it is certain that; of course","ko":"틀림없이 ~이다; 당연히 ~이다"},"formation":{"ja":"動詞普通形＋に決まっている / い形容詞普通形＋に決まっている / な形容詞語幹＋に決まっている / 名詞＋に決まっている","en":"動詞普通形＋に決まっている / い形容詞普通形＋に決まっている / な形容詞語幹＋に決まっている / 名詞＋に決まっている","ko":"動詞普通形＋に決まっている / い形容詞普通形＋に決まっている / な形容詞語幹＋に決まっている / 名詞＋に決まっている"},"examples":[{"ja":"何をするにも楽しいほうがいいに決まっている。","en":"Whatever you do, it is obviously better to enjoy it.","ko":"무엇을 하든 즐거운 편이 좋은 게 당연하다."}],"similar":[]},
  {"id":"d1725293495928","pattern":"〜に限って","core":"に限って","blankTarget":"に限って","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"他の場合は発生しない状況が、ある重要なときだけに偏って発生することを表します 後項では予想外のことが述べられます。","en":"only when; of all times; precisely in the case of","ko":"유독 ~할 때만; 하필 ~인 경우에만"},"formation":{"ja":"名詞＋に限って","en":"名詞＋に限って","ko":"名詞＋に限って"},"examples":[{"ja":"体調悪い時に限って予定が入ってくる。","en":"Plans always come up precisely when I am feeling unwell.","ko":"몸이 안 좋을 때만 유독 일정이 잡힌다."}],"similar":[]},
  {"id":"d1725293495927","pattern":"〜に限り／に限る","core":"に限り","blankTarget":"に限ります","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"限定を表します。 不特定多数の人への通知、通達に用います。 動詞「限る」の本来の意味としての使い方です。","en":"limited to; only; restricted to","ko":"~에 한하다; ~로 한정하다"},"formation":{"ja":"名詞＋に限り / 名詞＋に限る","en":"名詞＋に限り / 名詞＋に限る","ko":"名詞＋に限り / 名詞＋に限る"},"examples":[{"ja":"16歳未満の方の入場は保護者同伴に限ります。","en":"Admission for those under 16 is limited to those accompanied by a guardian.","ko":"16세 미만의 입장은 보호자 동반에 한합니다."}],"similar":[]},
  {"id":"d1725293495926","pattern":"〜に至る","core":"に至る","blankTarget":"に至る","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"物理的な空間への到達、物事や状況の変化の結果、結論などを表します。 書き言葉です。","en":"to reach; to come to; to lead to","ko":"~에 이르다; ~에 도달하다"},"formation":{"ja":"名詞＋に至る / 動詞辞書形＋に至る","en":"名詞＋に至る / 動詞辞書形＋に至る","ko":"名詞＋に至る / 動詞辞書形＋に至る"},"examples":[{"ja":"この川はＡ市内を通り、Ｂ市の海に至る。","en":"This river runs through City A and reaches the sea in City B.","ko":"이 강은 A시를 지나 B시의 바다에 이른다."}],"similar":[]},
  {"id":"d1725293495936","pattern":"〜に似合わず","core":"に似合わず","blankTarget":"に似合わず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"その人や物が有しているごく一般的な性質とは異なることを表します。","en":"unlike; uncharacteristically for; not befitting","ko":"~에 어울리지 않게; ~답지 않게"},"formation":{"ja":"名詞＋に似合わず","en":"名詞＋に似合わず","ko":"名詞＋に似合わず"},"examples":[{"ja":"彼はその体格に似合わず子供っぽいところがある。","en":"For his build, he has a surprisingly childish side.","ko":"그는 그 체격에 어울리지 않게 어린아이 같은 구석이 있다."}],"similar":[]},
  {"id":"d1725293495940","pattern":"〜に先駆け／に先駆けて","core":"に先駆け","blankTarget":"に先駆け","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①～の前に～する しておかなければならないことをまずしておくことを表します。 この用法のときは「～に先立って」に言い換えられます。 ②先駆者／パイオニア／先陣を切る 他の人よりも早く新しいことを始めることを表します。主に新しい分野の開拓に用います。 「世界に先駆け」「時代に先駆け」「他社に先駆け」など、比較となる対象に接続します。 「～に先駆けている」等の形でも用いることができます。","en":"ahead of; preceding; taking the lead in","ko":"~에 앞서; ~을 선도하여"},"formation":{"ja":"名詞＋に先駆け／に先駆けて / 動詞辞書形＋に先駆け／に先駆けて","en":"名詞＋に先駆け／に先駆けて / 動詞辞書形＋に先駆け／に先駆けて","ko":"名詞＋に先駆け／に先駆けて / 動詞辞書形＋に先駆け／に先駆けて"},"examples":[{"ja":"新年に先駆け、当店では一足早くセールを開催しています。","en":"Ahead of the new year, our store is holding an early sale.","ko":"새해에 앞서 저희 가게에서는 한발 앞서 세일을 진행하고 있습니다."}],"similar":[]},
  {"id":"d1725293495939","pattern":"〜に先立ち／に先立って","core":"に先立ち","blankTarget":"に先立ち","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"しておかなければならないことをまずしておくことを表します。 「～する前に～をしておく」という意味です。 後項に名詞が接続される場合は必ず「名詞＋に先立つ＋名詞」の形を取ります。「動詞辞書形＋に先立つ＋名詞」という形はありません。 「～に先駆け／に先駆けて」に言い換えられます。","en":"prior to; before; in advance of","ko":"~에 앞서; ~하기 전에"},"formation":{"ja":"名詞＋に先立ち／に先立って / 動詞辞書形＋に先立ち／に先立って / 名詞＋に先立つ＋名詞","en":"名詞＋に先立ち／に先立って / 動詞辞書形＋に先立ち／に先立って / 名詞＋に先立つ＋名詞","ko":"名詞＋に先立ち／に先立って / 動詞辞書形＋に先立ち／に先立って / 名詞＋に先立つ＋名詞"},"examples":[{"ja":"開演に先立ち、いくつかの注意事項をご説明いたします。","en":"Prior to the start of the performance, I will explain a few important points.","ko":"공연 시작에 앞서 몇 가지 주의 사항을 설명드리겠습니다."}],"similar":[]},
  {"id":"d1725293495946","pattern":"〜に相違ない","core":"に相違ない","blankTarget":"に相違ない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話し手の自信に満ちた強めの判断・断定を表します。 書き言葉として用いられます。","en":"undoubtedly; certainly; without a doubt","ko":"틀림없이 ~이다; 분명 ~이다"},"formation":{"ja":"動詞普通形＋に相違ない / い形容詞普通形＋に相違ない / な形容詞語幹＋に相違ない / 名詞＋に相違ない","en":"動詞普通形＋に相違ない / い形容詞普通形＋に相違ない / な形容詞語幹＋に相違ない / 名詞＋に相違ない","ko":"動詞普通形＋に相違ない / い形容詞普通形＋に相違ない / な形容詞語幹＋に相違ない / 名詞＋に相違ない"},"examples":[{"ja":"あの人が犯人に相違ない。","en":"That person is undoubtedly the culprit.","ko":"저 사람이 범인임에 틀림없다."}],"similar":[]},
  {"id":"d1725293495948","pattern":"〜に伴って／に伴い／に伴う","core":"に伴って","blankTarget":"に伴って","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項の変化に伴って後項も変化すること表す比例変化の表現です。 「～に伴って／に伴い」は文中で用い、「～に伴う」は後ろに名詞が接続されます。","en":"along with; as; accompanied by","ko":"~에 따라; ~에 수반하여"},"formation":{"ja":"名詞＋に伴って／に伴い／に伴う / 動詞辞書形＋の＋に伴って／に伴い／に伴う","en":"名詞＋に伴って／に伴い／に伴う / 動詞辞書形＋の＋に伴って／に伴い／に伴う","ko":"名詞＋に伴って／に伴い／に伴う / 動詞辞書形＋の＋に伴って／に伴い／に伴う"},"examples":[{"ja":"あらゆる物体が、それを構成する原子・分子の熱運動に伴って熱電波を出す現象のことを熱放射という。","en":"The phenomenon in which all objects emit thermal radiation along with the thermal motion of their constituent atoms and molecules is called thermal radiation.","ko":"모든 물체가 이를 구성하는 원자·분자의 열운동에 따라 열전파를 방출하는 현상을 열복사라고 한다."}],"similar":[]},
  {"id":"d1725293495924","pattern":"〜に反して／に反し／に反する","core":"に反して","blankTarget":"に反し","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"予想、予測などの未来を予測する語について結果がそれらの予測と逆であることや、意志や期待に背くことを表します。 「反する」はルールや規則などに違反するという意味もあります。","en":"contrary to; against; in violation of","ko":"~에 반하여; ~을 거스르고; ~에 위반하여"},"formation":{"ja":"名詞＋に反して／に反し / 名詞＋に反する","en":"名詞＋に反して／に反し / 名詞＋に反する","ko":"名詞＋に反して／に反し / 名詞＋に反する"},"examples":[{"ja":"大方の予想に反し、彼は金メダルを獲得した。","en":"Contrary to most people's expectations, he won the gold medal.","ko":"대다수의 예상에 반하여 그는 금메달을 획득했다."}],"similar":[]},
  {"id":"d1725293495951","pattern":"〜のことだから／のことだ","core":"のことだから","blankTarget":"のことだから","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"特定の人物を表す語につき、その人物が習慣的、性格的に何らかの特徴があることを表します。後件ではその特徴が根拠となり、話者の主観的な判断が述べられます。 話者とその人物は比較的近い関係でなければいけません。","en":"knowing (someone); given that it is (someone); because of who (someone) is","ko":"~인 걸 아니까; ~이니까 (그 사람의 성격상)"},"formation":{"ja":"名詞＋のことだから / 名詞＋のことだ。（文末）","en":"名詞＋のことだから / 名詞＋のことだ。（文末）","ko":"名詞＋のことだから / 名詞＋のことだ。（文末）"},"examples":[{"ja":"あの２人のことだから、私たちがいなくても何とか大丈夫だろう。","en":"Knowing those two, they will probably manage somehow even without us.","ko":"저 두 사람이니까 우리가 없어도 어떻게든 괜찮겠지."}],"similar":[]},
  {"id":"d1725293495950","pattern":"〜のは〜くらいだ／〜のは〜くらいのものだ／〜のは〜ぐらいだ／〜のは〜ぐらいのものだ","core":"のは〜くらいだ","blankTarget":"のは","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"後件の人物や状況でなければ前件が成り立たないこと、成し遂げられないことを表します。 後件には人物の名前や状況を表す名詞が接続されます。 「【Ｎ３文法】～しか～ない」と同じ意味ですが、ニュアンスが異なります。「～しか～ない」は話者の不満や残念な感情を含みますが、「～のは～くらいだ」はそうとは限らず、良い内容にも悪い内容にも用いることができます。","en":"only when; the only one who; it is only ... that","ko":"~하는 것은 ~할 때뿐이다; 오직 ~만이 ~하다"},"formation":{"ja":"動詞普通形＋のは＋名詞＋くらいだ / 動詞普通形＋のは＋名詞＋くらいのものだ","en":"動詞普通形＋のは＋名詞＋くらいだ / 動詞普通形＋のは＋名詞＋くらいのものだ","ko":"動詞普通形＋のは＋名詞＋くらいだ / 動詞普通形＋のは＋名詞＋くらいのものだ"},"examples":[{"ja":"彼が連絡をよこすのは何か面倒なことが起きたときくらいだ。","en":"The only time he contacts me is when something troublesome has happened.","ko":"그가 연락을 해 오는 것은 뭔가 귀찮은 일이 생겼을 때뿐이다."}],"similar":[]},
  {"id":"d1725293495952","pattern":"〜のみならず／〜のみか","core":"のみならず","blankTarget":"のみならず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項で述べたものに加え、更にそれ以上のことを後項で述べる累加・添加の文法です。 前項では「ただ」、後項ではよく「も」などが呼応します。 「のみならず」は書き言葉です。 「～にとどまらず」「～だけでなく」「～ばかりでなく」に自由に言い換えることができます。","en":"not only ... but also; not merely","ko":"~뿐만 아니라; ~은 물론"},"formation":{"ja":"動詞普通形＋のみならず／のみか / い形容詞普通形＋のみならず／のみか / な形容詞語幹＋である＋のみならず／のみか / 名詞（＋である）＋のみならず／のみか","en":"動詞普通形＋のみならず／のみか / い形容詞普通形＋のみならず／のみか / な形容詞語幹＋である＋のみならず／のみか / 名詞（＋である）＋のみならず／のみか","ko":"動詞普通形＋のみならず／のみか / い形容詞普通形＋のみならず／のみか / な形容詞語幹＋である＋のみならず／のみか / 名詞（＋である）＋のみならず／のみか"},"examples":[{"ja":"彼女は英語のみならず、中国語までできる。","en":"She can speak not only English but Chinese as well.","ko":"그녀는 영어뿐만 아니라 중국어까지 할 수 있다."}],"similar":[]},
  {"id":"d1725293495867","pattern":"〜は〜に限る","core":"は〜に限る","blankTarget":"は","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"主観的な判断や印象によって最も良いと思うものを述べるときに使います。 自分の意見を述べる場合に使うので、客観的な意見には使えません。 前項に「やっぱり」がよく呼応します。","en":"nothing beats; the best is; there is nothing like","ko":"~이 최고다; ~만 한 것이 없다"},"formation":{"ja":"動詞辞書形＋に限る / 動ない形＋ないに限る / な形容詞語幹＋なのに限る / い形容詞＋のに限る / 名詞＋に限る","en":"動詞辞書形＋に限る / 動ない形＋ないに限る / な形容詞語幹＋なのに限る / い形容詞＋のに限る / 名詞＋に限る","ko":"動詞辞書形＋に限る / 動ない形＋ないに限る / な形容詞語幹＋なのに限る / い形容詞＋のに限る / 名詞＋に限る"},"examples":[{"ja":"暑い夏の仕事終わりはやっぱりビールに限る。","en":"After a hot summer day's work, nothing beats a beer.","ko":"더운 여름 퇴근 후에는 역시 맥주가 최고다."}],"similar":[]},
  {"id":"d1725293495869","pattern":"〜はおろか","core":"はおろか","blankTarget":"はおろか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"Ａはおろか、Ｂも～ない Ａはおろか、Ｂすら～ない Ａはおろか、Ｂさえ～ない Ａはおろか、Ｂまで～ない 「Ａはおろか、Ｂも～ない」の形でよく使われます。 後件ではマイナスの評価が述べられ、否定的な表現が来ます。後件で取り上げるものは前件よりも程度が高くなければいけません。 「も」「すら」「さえ」「まで」などがよく呼応します。","en":"let alone; not to mention; to say nothing of","ko":"~은커녕; ~은 말할 것도 없고"},"formation":{"ja":"名詞＋はおろか＋名詞＋も／すら／さえ／まで＋～ない / 動詞普通形＋の＋はおろか＋名詞＋も／すら／さえ／まで＋～ない","en":"名詞＋はおろか＋名詞＋も／すら／さえ／まで＋～ない / 動詞普通形＋の＋はおろか＋名詞＋も／すら／さえ／まで＋～ない","ko":"名詞＋はおろか＋名詞＋も／すら／さえ／まで＋～ない / 動詞普通形＋の＋はおろか＋名詞＋も／すら／さえ／まで＋～ない"},"examples":[{"ja":"正社員はおろか、アルバイトすらなかなか見つからない。","en":"Full-time positions are out of the question; I cannot even find a part-time job.","ko":"정사원은커녕 아르바이트조차 좀처럼 구하기 어렵다."}],"similar":[]},
  {"id":"d1725293495846","pattern":"〜ばかりか","core":"ばかりか","blankTarget":"ばかりか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項で述べたものに加え、更にそれ以上のことを後項で述べる累加・添加の文法です。 後項ではよく「も」などが呼応します。 意味は「【Ｎ３文法】～ばかりでなく～も／～ばかりでなくて～も」と同じですが、「～ばかりか」のほうが硬い表現です。","en":"not only ... but also; not just","ko":"~뿐만 아니라; ~은 물론"},"formation":{"ja":"動詞普通形＋ばかりか / な形容詞語幹＋な／である＋ばかりか / い形容詞普通形＋ばかりか / 名詞＋ばかりか","en":"動詞普通形＋ばかりか / な形容詞語幹＋な／である＋ばかりか / い形容詞普通形＋ばかりか / 名詞＋ばかりか","ko":"動詞普通形＋ばかりか / な形容詞語幹＋な／である＋ばかりか / い形容詞普通形＋ばかりか / 名詞＋ばかりか"},"examples":[{"ja":"助けてと言っても助けてくれないばかりか、笑ってこっちを見る始末だ。","en":"Not only does he refuse to help when I ask, but he ends up laughing and staring at me.","ko":"도와달라고 해도 도와주지 않을 뿐만 아니라 웃으면서 이쪽을 보기까지 한다."}],"similar":[]},
  {"id":"d1725293495847","pattern":"〜ばかりに","core":"ばかりに","blankTarget":"ばかりに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"悪い原因を表します。後項にはそれによって発生した、話し手にとって意外性のある悪い結果を述べます。","en":"just because; simply because (leading to a bad result)","ko":"~때문에; ~한 탓에"},"formation":{"ja":"動詞普通形＋ばかりに / い形容詞普通形＋ばかりに / 名詞＋（な／である）＋ばかりに / な形容詞＋（な／である）＋ばかりに","en":"動詞普通形＋ばかりに / い形容詞普通形＋ばかりに / 名詞＋（な／である）＋ばかりに / な形容詞＋（な／である）＋ばかりに","ko":"動詞普通形＋ばかりに / い形容詞普通形＋ばかりに / 名詞＋（な／である）＋ばかりに / な形容詞＋（な／である）＋ばかりに"},"examples":[{"ja":"周囲が反対しているばかりに、留学できずにいる。","en":"Just because those around me are opposed, I am unable to study abroad.","ko":"주변에서 반대하는 탓에 유학을 가지 못하고 있다."}],"similar":[]},
  {"id":"d1725293495871","pattern":"〜はずだった／はずではなかった","core":"はずだった","blankTarget":"はずだった","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話者が想定していた出来事が起きなかったこと対する残念な感情を表します。 後件にはよく逆接の表現がきます。 「こんなはずじゃなかったのに」はよく使われる表現です。","en":"was supposed to; should have been (but was not); was not supposed to","ko":"~하기로 되어 있었다; ~이어야 했다; ~이 아니어야 했다"},"formation":{"ja":"名詞＋のはずだった／はずではなかった / い形容詞普通形＋はずだった／はずではなかった / な形容詞語幹＋な／である＋はずだった／はずではなかった / 動詞普通形＋はずだった／はずではなかった","en":"名詞＋のはずだった／はずではなかった / い形容詞普通形＋はずだった／はずではなかった / な形容詞語幹＋な／である＋はずだった／はずではなかった / 動詞普通形＋はずだった／はずではなかった","ko":"名詞＋のはずだった／はずではなかった / い形容詞普通形＋はずだった／はずではなかった / な形容詞語幹＋な／である＋はずだった／はずではなかった / 動詞普通形＋はずだった／はずではなかった"},"examples":[{"ja":"来るはずだったアルバイトの子から来れなくなったと連絡が来た。","en":"I got a message from the part-timer who was supposed to come, saying they could not make it.","ko":"오기로 했던 아르바이트생에게서 못 오게 되었다는 연락이 왔다."}],"similar":[]},
  {"id":"d1725293495870","pattern":"〜はともかく(として)","core":"はともかく(として)","blankTarget":"はともかくとして","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項の内容については考えず、まず後項について触れることを表します。 「【Ｎ２文法】～は別にして／は別として」と同じです。","en":"leaving aside; setting aside; regardless of","ko":"~은 제쳐 두고; ~은 어쨌든"},"formation":{"ja":"名詞＋はともかく（として） / 動詞普通形＋かどうかはともかく（として） / い形容詞普通形＋かどうかはともかく（として） / な形容詞普通形＋かどうかはともかく（として）","en":"名詞＋はともかく（として） / 動詞普通形＋かどうかはともかく（として） / い形容詞普通形＋かどうかはともかく（として） / な形容詞普通形＋かどうかはともかく（として）","ko":"名詞＋はともかく（として） / 動詞普通形＋かどうかはともかく（として） / い形容詞普通形＋かどうかはともかく（として） / な形容詞普通形＋かどうかはともかく（として）"},"examples":[{"ja":"結果はともかくとして、そこまでの道中が大変だった。","en":"Never mind the result; the journey there was tough.","ko":"결과는 제쳐 두고 거기까지 가는 길이 힘들었다."}],"similar":[]},
  {"id":"d1725293495866","pattern":"〜はもとより／はもちろん","core":"はもとより","blankTarget":"はもとより","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項で代表的な物事を挙げ、それは言うまでもなく自明であることを表します。 また、後項では前項と同程度の物事について触れ、それについても同様であることを表します。 「～はもちろん」は口語で、「～はもとより」は口語だけでなく書き言葉としても用いられます。","en":"not to mention; to say nothing of; of course","ko":"~은 물론; ~은 말할 것도 없이"},"formation":{"ja":"名詞＋はもとより / 名詞＋はもちろん","en":"名詞＋はもとより / 名詞＋はもちろん","ko":"名詞＋はもとより / 名詞＋はもちろん"},"examples":[{"ja":"この車はデザインはもとより、燃費もいい。","en":"This car not only looks good but also has excellent fuel efficiency.","ko":"이 차는 디자인은 물론 연비도 좋다."}],"similar":[]},
  {"id":"d1725293495865","pattern":"〜は別にして／は別として","core":"は別にして","blankTarget":"は別にして","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項の内容については考えず、まず後項について触れることを表します。 「【Ｎ２文法】～はともかく（として）」と同じです。","en":"apart from; setting aside; regardless of","ko":"~은 별개로 하고; ~은 따로 치고"},"formation":{"ja":"名詞＋は別にして／は別として / 動詞普通形＋かどうかは別にして／は別として / い形容詞普通形＋かどうかは別にして／は別として / な形容詞普通形＋かどうかは別にして／は別として","en":"名詞＋は別にして／は別として / 動詞普通形＋かどうかは別にして／は別として / い形容詞普通形＋かどうかは別にして／は別として / な形容詞普通形＋かどうかは別にして／は別として","ko":"名詞＋は別にして／は別として / 動詞普通形＋かどうかは別にして／は別として / い形容詞普通形＋かどうかは別にして／は別として / な形容詞普通形＋かどうかは別にして／は別として"},"examples":[{"ja":"勝ち負けは別にして、ゲームはみんなでやると楽しい。","en":"Setting aside winning or losing, games are fun when everyone plays together.","ko":"승패는 별개로 하고 게임은 다 같이 하면 즐겁다."}],"similar":[]},
  {"id":"d1725293495872","pattern":"〜ほど〜は〜ない／〜くらい〜は〜ない","core":"ほど〜は〜ない","blankTarget":"ほど","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"物事が最高の程度に達して、それ以上ないことを表します。 後件に否定形を伴い、「～くらい～ない」の文型を取ります。 後件には「少ない」「珍しい」「他にない」「いない」「存在しない」などの語が続きます。","en":"there is nothing more ... than; nothing is as ... as","ko":"~만큼 ~한 것은 없다; ~이 가장 ~하다"},"formation":{"ja":"名詞＋ほど＋名詞＋は～ない / 名詞＋くらい＋名詞＋は～ない / 名詞＋ぐらい＋名詞＋は～ない","en":"名詞＋ほど＋名詞＋は～ない / 名詞＋くらい＋名詞＋は～ない / 名詞＋ぐらい＋名詞＋は～ない","ko":"名詞＋ほど＋名詞＋は～ない / 名詞＋くらい＋名詞＋は～ない / 名詞＋ぐらい＋名詞＋は～ない"},"examples":[{"ja":"囲碁ほどルールを聞いても分からない盤上競技は他にない。","en":"There is no other board game as hard to understand as Go, even after hearing the rules.","ko":"바둑만큼 규칙을 들어도 이해가 안 되는 보드게임은 없다."}],"similar":[]},
  {"id":"d1725293495904","pattern":"〜まい","core":"まい","blankTarget":"まい","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①否定意志 「～ないつもりだ」「～ないようにしよう」と同義です。 ②否定推量 「～ないだろう」と同義です。 書き言葉で用いることが多い硬い表現です。","en":"will not; intend not to; probably not","ko":"~하지 않겠다; ~하지 않을 것이다; 아마 ~하지 않을 것이다"},"formation":{"ja":"五段動詞辞書形＋まい（書くまい） / 一段動詞辞書形＋まい（見るまい） / 一段動詞ます形＋まい（見まい） / する → するまい／しまい／すまい / 来る → 来るまい（くるまい）／来まい（こまい）／来まい（くまい）","en":"五段動詞辞書形＋まい（書くまい） / 一段動詞辞書形＋まい（見るまい） / 一段動詞ます形＋まい（見まい） / する → するまい／しまい／すまい / 来る → 来るまい（くるまい）／来まい（こまい）／来まい（くまい）","ko":"五段動詞辞書形＋まい（書くまい） / 一段動詞辞書形＋まい（見るまい） / 一段動詞ます形＋まい（見まい） / する → するまい／しまい／すまい / 来る → 来るまい（くるまい）／来まい（こまい）／来まい（くまい）"},"examples":[{"ja":"これ以上は何も言うまい。","en":"I will say no more.","ko":"더 이상은 아무 말도 하지 않겠다."}],"similar":[]},
  {"id":"d1725293495905","pattern":"〜まいとする／まいとして","core":"まいとする","blankTarget":"まいとして","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"否定の目的を表します。「～ないために」と同義です。 「～まいと／まいとして」の形で多く用いられます。 書き言葉で用いることが多い硬い表現です。","en":"trying not to; so as not to; in order not to","ko":"~하지 않으려고; ~하지 않도록"},"formation":{"ja":"五段動詞辞書形＋まいとする / 一段動詞辞書形＋まいとする / 一段動詞ます形＋まいとする / する→するまいとする／しまいとする / 来る→来るまい（くるまい）とする／来まい（こまい）とする","en":"五段動詞辞書形＋まいとする / 一段動詞辞書形＋まいとする / 一段動詞ます形＋まいとする / する→するまいとする／しまいとする / 来る→来るまい（くるまい）とする／来まい（こまい）とする","ko":"五段動詞辞書形＋まいとする / 一段動詞辞書形＋まいとする / 一段動詞ます形＋まいとする / する→するまいとする／しまいとする / 来る→来るまい（くるまい）とする／来まい（こまい）とする"},"examples":[{"ja":"親に心配をかけまいとして、我慢しながら今の仕事を続けている。","en":"So as not to worry my parents, I keep enduring and staying in my current job.","ko":"부모님께 걱정을 끼치지 않으려고 참으면서 지금 일을 계속하고 있다."}],"similar":[]},
  {"id":"d1725293495903","pattern":"〜までになる","core":"までになる","blankTarget":"までになった","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"長時間に及ぶ努力で、現在の結果や状態になったことを表します。変化や成長の過程を含意します。 基本、良い結果や状態に使います。 「なる」以外の代わりに変化動詞「変わる」「変化する」「進歩する」「成長する」なども使えます。","en":"to reach the point of; to come to (after long effort)","ko":"~하는 지경에 이르다; ~할 정도가 되다"},"formation":{"ja":"動詞辞書形＋までになる","en":"動詞辞書形＋までになる","ko":"動詞辞書形＋までになる"},"examples":[{"ja":"昨日は体調が悪かったけどなんとか動けるまでになった。","en":"Yesterday I felt unwell, but I managed to reach the point where I could move around.","ko":"어제는 몸이 안 좋았지만 겨우 움직일 수 있는 정도가 되었다."}],"similar":[]},
  {"id":"d1725293495906","pattern":"〜まま／ままに","core":"まま","blankTarget":"まま","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"自分が思うように好きなことをすることを表します。 自然に任せるようなニュアンスがあります。 接続できる動詞は「気の向くまま」「足の向くまま」「思うまま」など限られています。 「～を欲しいままにする」は権力、名声、名などの語について、それらを全て手に入れたこと、独り占めすることを表します。","en":"as one pleases; at will; following (one's feelings)","ko":"~대로; ~하는 대로; 마음껏"},"formation":{"ja":"動詞辞書形＋まま（に）","en":"動詞辞書形＋まま（に）","ko":"動詞辞書形＋まま（に）"},"examples":[{"ja":"時間と金に囚われず気の向くままゆっくりと旅したい。","en":"I want to travel slowly wherever my mood takes me, free from time and money.","ko":"시간과 돈에 얽매이지 않고 마음 가는 대로 느긋하게 여행하고 싶다."}],"similar":[]},
  {"id":"d1752122921184","pattern":"〜み","core":"み","blankTarget":"み","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"イ形容詞語幹について、主観的な感覚や状態を表します。「～み」がつけられるイ形容詞は３０ほどしかなく（伊藤・杉岡 2016: 125）、「～さ」に比べると生産性・造語力はとても低いです。ナ形容詞に「～み」を接続する例として「真剣み」「堅実み」などがありそうですが、基本的にナ形容詞には接続できないものとして考えてもいいと思います。また、「～み」を付けると名詞になります。 ※「恨む」に対する「恨み」、「憎む」に対する「憎み」なども一見すると「～み」がついているように見えますが、この「み」は動詞のマス形に現れる「み」であって、「重み」などの「み」とは異なるものです。","en":"-ness; degree of (a state or feeling)","ko":"~함; ~정도 (형용사 어간에 붙어 명사를 만듦)"},"formation":{"ja":"イ形容詞語幹＋み","en":"イ形容詞語幹＋み","ko":"イ形容詞語幹＋み"},"examples":[{"ja":"本棚が本の重みで破壊された。","en":"The bookshelf was destroyed by the weight of the books.","ko":"책장이 책의 무게 때문에 부서졌다."}],"similar":[]},
  {"id":"d1752122528914","pattern":"〜め","core":"め","blankTarget":"め","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"イ形容詞の語幹について、その性質や状態の傾向があることを表します。例えば「早め」というと、早くも遅くもない中間地点からやや早い方向に傾いた状態を表します。「～めに＋動詞」の形で動詞を副詞的に修飾することが可能です。 ※「濃い（ko-i）」は語幹に「め」をつけて「濃め」とは言わず、「濃いめ」と言います。","en":"somewhat; rather; on the ... side","ko":"약간 ~한 편; 다소 ~하게"},"formation":{"ja":"イ形容詞語幹＋め / ※濃い→濃いめ","en":"イ形容詞語幹＋め / ※濃い→濃いめ","ko":"イ形容詞語幹＋め / ※濃い→濃いめ"},"examples":[{"ja":"明日は早めに来てください。","en":"Please come a little early tomorrow.","ko":"내일은 조금 일찍 와 주세요."}],"similar":[]},
  {"id":"d1725293495913","pattern":"〜ものか／もんか／ものですか／もんですか","core":"ものか","blankTarget":"もんか","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"話者の非常に強い否定・拒絶の表現です。強い否定のため、反発的な態度を表します。 「もんか／もんですか」は「ものか／ものですか」の口語にあたります。 男性は一般に「ものか／もんか」を使い、女性は「ものですか／もんですか」を使うことが多いです。","en":"no way; I will never; as if (strong denial)","ko":"결코 ~하지 않겠다; ~할까 보냐"},"formation":{"ja":"動詞辞書形＋ものか／もんか／ものですか／もんですか / な形容詞＋な＋ものか／もんか／ものですか／もんですか / い形容詞＋ものか／もんか／ものですか／もんですか","en":"動詞辞書形＋ものか／もんか／ものですか／もんですか / な形容詞＋な＋ものか／もんか／ものですか／もんですか / い形容詞＋ものか／もんか／ものですか／もんですか","ko":"動詞辞書形＋ものか／もんか／ものですか／もんですか / な形容詞＋な＋ものか／もんか／ものですか／もんですか / い形容詞＋ものか／もんか／ものですか／もんですか"},"examples":[{"ja":"あいつに負けてたまるもんか。","en":"I am not about to lose to that guy.","ko":"저 녀석한테 지고 말겠냐."}],"similar":[]},
  {"id":"d1725293495912","pattern":"〜ものがある","core":"ものがある","blankTarget":"ものがある","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「ＡにはＢものがある」「ＡのはＢものがある」などの形で用いられます。この時、Ａの中にある性質や属性をＢで表します。客観的な表現です。","en":"there is something ... about it; has a certain quality","ko":"~한 면이 있다; ~한 점이 있다"},"formation":{"ja":"動詞普通形＋ものがある / な形容詞語幹＋な＋ものがある / い形容詞原形＋ものがある","en":"動詞普通形＋ものがある / な形容詞語幹＋な＋ものがある / い形容詞原形＋ものがある","ko":"動詞普通形＋ものがある / な形容詞語幹＋な＋ものがある / い形容詞原形＋ものがある"},"examples":[{"ja":"彼女の人気は根強いものがある。","en":"There is something deeply rooted about her popularity.","ko":"그녀의 인기에는 뿌리 깊은 면이 있다."}],"similar":[]},
  {"id":"d1725293495909","pattern":"〜ものだ","core":"ものだ","blankTarget":"ものだ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①物事の本質や真理、一般常識を述べる ②物事に対する強い感情を表す いずれの場合も、話者自らの感情が強く含まれます。 口語では「～もんだ」となります。","en":"is supposed to be; it is only natural that; how ... (deep emotion)","ko":"~란 원래 ~한 것이다; 정말 ~하구나"},"formation":{"ja":"動詞普通形＋ものだ / な形容詞語幹＋な／である＋ものだ / い形容詞＋ものだ","en":"動詞普通形＋ものだ / な形容詞語幹＋な／である＋ものだ / い形容詞＋ものだ","ko":"動詞普通形＋ものだ / な形容詞語幹＋な／である＋ものだ / い形容詞＋ものだ"},"examples":[{"ja":"英雄とは、死して初めて歴史に名を残すものだ。","en":"A hero is one who leaves a name in history only after death.","ko":"영웅이란 죽은 뒤에야 역사에 이름을 남기는 법이다."}],"similar":[]},
  {"id":"d1725293495910","pattern":"〜ものだから／もんだから","core":"ものだから","blankTarget":"ものだから","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"理由、原因を表します。 この文法は、前件の程度がひどいので後件の状態になったことを述べるときに用いるのが特徴です。 過去のことにしか使えません。 「もんだから」は口語です。","en":"because; since (offering a reason or excuse)","ko":"~하는 바람에; ~인지라"},"formation":{"ja":"動詞普通形＋ものだから／もんだから / イ形普通形＋ものだから／もんだから / ナ形語幹＋な＋ものだから／もんだから / 名詞＋な＋ものだから／もんだから","en":"動詞普通形＋ものだから／もんだから / イ形普通形＋ものだから／もんだから / ナ形語幹＋な＋ものだから／もんだから / 名詞＋な＋ものだから／もんだから","ko":"動詞普通形＋ものだから／もんだから / イ形普通形＋ものだから／もんだから / ナ形語幹＋な＋ものだから／もんだから / 名詞＋な＋ものだから／もんだから"},"examples":[{"ja":"夜蚊に起こされたものだから寝不足で頭痛がひどい。","en":"I was woken up by mosquitoes at night, so I am sleep-deprived and have a terrible headache.","ko":"밤에 모기에 깨는 바람에 잠을 못 자서 머리가 심하게 아프다."}],"similar":[]},
  {"id":"d1725293495911","pattern":"〜ものではない／もんじゃない","core":"ものではない","blankTarget":"ものではない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"人の行為を表す動詞について、そうするべきではないという忠告やアドバイスを表します。 社会常識や物事の真理等によって行動規範が客観的に決まっている場合にこの文法を使うことができます。 口語は「～もんじゃない」です。","en":"should not; one ought not to","ko":"~해서는 안 된다; ~할 것이 아니다"},"formation":{"ja":"動詞辞書形＋ものではない","en":"動詞辞書形＋ものではない","ko":"動詞辞書形＋ものではない"},"examples":[{"ja":"人のことに首を突っ込むものではない。","en":"You should not poke your nose into other people's business.","ko":"남의 일에 참견해서는 안 된다."}],"similar":[]},
  {"id":"d1725293495914","pattern":"〜ものなら／もんなら","core":"ものなら","blankTarget":"もんなら","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"実現する可能性が非常に低い物事が実現することを強く願う話者の願望や期待を表します。 多くの場合、動詞可能形に接続します。 また、例文（７）（８）のように相手を煽るような表現としても使えます。 口語では「もんなら」となります。","en":"if only one could; if it were possible to","ko":"~할 수 있다면; ~라면"},"formation":{"ja":"動可能形＋ものなら／もんなら / 動詞辞書形＋ものなら／もんなら","en":"動可能形＋ものなら／もんなら / 動詞辞書形＋ものなら／もんなら","ko":"動可能形＋ものなら／もんなら / 動詞辞書形＋ものなら／もんなら"},"examples":[{"ja":"寝れるもんなら一生寝ていたい。","en":"If I could sleep, I would sleep for the rest of my life.","ko":"잘 수 있다면 평생 잠만 자고 싶다."}],"similar":[]},
  {"id":"d1725293495915","pattern":"〜ものの","core":"ものの","blankTarget":"ものの","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"既に発生したこと対して用いる。 「しかし」とほぼ同じで、それよりも硬い表現。 後項には、前項に対応する事柄がまだ行われていないか、通常起こらない、起こりそうにないことを述べる。 後項には自信がなかったり、実現困難なことが続くことが多い。","en":"although; even though; but","ko":"~이기는 하지만; ~기는 하나"},"formation":{"ja":"動詞名詞修飾形＋ものの / な形容詞動詞修飾形＋ものの / い形容詞動詞修飾形＋ものの / 名詞＋である＋ものの","en":"動詞名詞修飾形＋ものの / な形容詞動詞修飾形＋ものの / い形容詞動詞修飾形＋ものの / 名詞＋である＋ものの","ko":"動詞名詞修飾形＋ものの / な形容詞動詞修飾形＋ものの / い形容詞動詞修飾形＋ものの / 名詞＋である＋ものの"},"examples":[{"ja":"五十音は発音できるようになったものの、書けと言われれば自信がない。","en":"I can now pronounce the kana, but I am not confident about writing them.","ko":"오십음은 발음할 수 있게 되었지만 쓰라고 하면 자신이 없다."}],"similar":[]},
  {"id":"d1725293495908","pattern":"〜も構わず(かまわず)","core":"も構わず(かまわず)","blankTarget":"も構わず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"デメリットやリスク、危険性などの通常気にするようなことを気にせずに何らかの動作を行うことを表します。 「人目も構わず（不顾及别人的目光）」「所構わず」「なりふり構わず」は慣用句です。","en":"without caring about; regardless of; in defiance of","ko":"~도 아랑곳하지 않고; ~을 개의치 않고"},"formation":{"ja":"名詞＋も構わず / 名詞＋にも構わず / 動詞普通形＋のも構わず / 動詞普通形＋のにも構わず","en":"名詞＋も構わず / 名詞＋にも構わず / 動詞普通形＋のも構わず / 動詞普通形＋のにも構わず","ko":"名詞＋も構わず / 名詞＋にも構わず / 動詞普通形＋のも構わず / 動詞普通形＋のにも構わず"},"examples":[{"ja":"お互い駆け寄って人目も構わず抱き合った。","en":"They ran toward each other and embraced without caring about the people around them.","ko":"서로 달려가 남의 이목도 아랑곳하지 않고 끌어안았다."}],"similar":[]},
  {"id":"d1725293495916","pattern":"〜も当然だ","core":"も当然だ","blankTarget":"も当然だ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"多くは「Ａ、Ｂも当然だ」の形を取り、前項（Ａ）が理由・原因となって後項（Ｂ）が生じたことは自然な結果、当然の結果であることを表します。 話者の主観的な判断が含まれます。","en":"it is only natural that ...; no wonder ...","ko":"…하는 것도 당연하다; …한 것도 당연하다"},"formation":{"ja":"名詞＋も当然だ / 動詞普通形＋のも当然だ / な形容詞＋なのも当然だ / い形容詞普通形＋のも当然だ","en":"名詞＋も当然だ / 動詞普通形＋のも当然だ / な形容詞＋なのも当然だ / い形容詞普通形＋のも当然だ","ko":"名詞＋も当然だ / 動詞普通形＋のも当然だ / な形容詞＋なのも当然だ / い形容詞普通形＋のも当然だ"},"examples":[{"ja":"あんなに失礼な態度を取られたら怒るのも当然だ。","en":"If someone treats you with such a disrespectful attitude, it's only natural to get angry.","ko":"그렇게 무례한 태도를 당한다면 화가 나는 것도 당연하다."}],"similar":[]},
  {"id":"d1725293496011","pattern":"〜ようで／ようでいて","core":"ようで","blankTarget":"ようで","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"見た感じの印象と実際とは異なることを表します。 前項では「一見」、後項では「実は」「本当は」などの言葉がよく呼応します。","en":"seemingly ... but actually; looks like ... yet","ko":"…인 것 같지만 사실은; …처럼 보이지만"},"formation":{"ja":"動詞普通形＋ようで／ようでいて / い形容詞＋ようで／ようでいて / な形容詞語幹＋な＋ようで／ようでいて / 名詞＋の＋ようで／ようでいて","en":"動詞普通形＋ようで／ようでいて / い形容詞＋ようで／ようでいて / な形容詞語幹＋な＋ようで／ようでいて / 名詞＋の＋ようで／ようでいて","ko":"動詞普通形＋ようで／ようでいて / い形容詞＋ようで／ようでいて / な形容詞語幹＋な＋ようで／ようでいて / 名詞＋の＋ようで／ようでいて"},"examples":[{"ja":"祈りと願いは、同じようで全然違うものだ。","en":"Prayer and a wish may seem the same, but they are completely different.","ko":"기도와 소원은 비슷해 보이지만 전혀 다른 것이다."}],"similar":[]},
  {"id":"d1725293496012","pattern":"〜ようでは／ないようでは","core":"ようでは","blankTarget":"ようでは","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前項で述べたことが仮に実現すれば、期待される結果とはならないことを表します。 後項にはよく「だめ」「困る」「～ない」などの良くない内容がきます。","en":"if things are like this, (it's hopeless); if one is at the level of ...","ko":"…하는 정도라면 (안 된다); …할 정도라면"},"formation":{"ja":"動詞辞書形＋ようでは / 動ない形＋ないようでは","en":"動詞辞書形＋ようでは / 動ない形＋ないようでは","ko":"動詞辞書形＋ようでは / 動ない形＋ないようでは"},"examples":[{"ja":"どんなに苦しくても、人にそれを気づかれるようではいけない。","en":"No matter how hard it gets, you mustn't let anyone notice it.","ko":"아무리 괴로워도 남에게 그걸 눈치채이게 해서는 안 된다."}],"similar":[]},
  {"id":"d1725293496015","pattern":"〜ようなら／ようだったら／ようであれば／ようでしたら","core":"ようなら","blankTarget":"ないようなら","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"仮定条件を表します。 「ようであれば」はやや硬めの表現です。","en":"if; in the case that; if it seems that","ko":"…라면; …인 것 같으면"},"formation":{"ja":"動詞辞書形＋ようなら / 動ない形＋ないようなら / な形容詞語幹＋な／である＋ようなら / い形容詞普通形＋ようなら","en":"動詞辞書形＋ようなら / 動ない形＋ないようなら / な形容詞語幹＋な／である＋ようなら / い形容詞普通形＋ようなら","ko":"動詞辞書形＋ようなら / 動ない形＋ないようなら / な形容詞語幹＋な／である＋ようなら / い形容詞普通形＋ようなら"},"examples":[{"ja":"このレベルが理解できないようなら、君才能ないよ。","en":"If you can't even understand this level, you have no talent.","ko":"이 수준을 이해하지 못한다면 넌 재능이 없는 거야."}],"similar":[]},
  {"id":"d1725293496010","pattern":"〜よりむしろ〜／むしろ〜","core":"よりむしろ〜","blankTarget":"よりむしろ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"二つの物事を比較し、後件の内容の方がより適当であることを表します。","en":"rather than ...; ... is more like it; rather","ko":"…보다는 오히려; 차라리"},"formation":{"ja":"名詞＋よりむしろ～ / 動詞辞書形＋よりむしろ～ / 動ている形＋よりむしろ～ / [接続詞]むしろ～","en":"名詞＋よりむしろ～ / 動詞辞書形＋よりむしろ～ / 動ている形＋よりむしろ～ / [接続詞]むしろ～","ko":"名詞＋よりむしろ～ / 動詞辞書形＋よりむしろ～ / 動ている形＋よりむしろ～ / [接続詞]むしろ～"},"examples":[{"ja":"私はたこ焼きよりむしろお好み焼き派だ。","en":"I'm more of an okonomiyaki person than a takoyaki person.","ko":"나는 타코야키보다 오히려 오코노미야키 쪽이다."}],"similar":[]},
  {"id":"d1725293496002","pattern":"〜をきっかけにして／がきっかけで／がきっかけになって","core":"をきっかけにして","blankTarget":"をきっかけに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"新しい事柄が始まるその起点を表します。前項にはその起点、後項にはその後の行為を述べます。「～を機に／を契機に」に言い換えることができますが、こちらはやや硬めな表現です。一方、「～をきっかけに」は口語でよく用いられる表現です。 前項と後項が同種の行為の時、この文型は使えません。前項と後項は全く異なる行為を述べ、前項が機会や動機となって後項とするという時に使えます。 ✕大阪への旅行をきっかけに、京都にも旅行した。 ◯大阪への旅行を皮切りに、京都にも旅行した。 このような場合は「～を皮切りに」が使えます。 他動詞自動詞普通の表現～をきっかけに ～をきっかけにして ～のをきっかけに ～のをきっかけにして～がきっかけで ～がきっかけになって ～のがきっかけで ～のがきっかけになってやや硬い表現～をきっかけとして ～のをきっかけとして～がきっかけとなって ～のがきっかけとなって","en":"triggered by; taking ... as an opportunity; as a result of","ko":"…을 계기로; …을 기회로; …이 계기가 되어"},"formation":{"ja":"名詞＋をきっかけに（して） / 名詞＋をきっかけとして / 動普通形＋のをきっかけに（して） / 動普通形＋のをきっかけとして / 名詞＋がきっかけで","en":"名詞＋をきっかけに（して） / 名詞＋をきっかけとして / 動普通形＋のをきっかけに（して） / 動普通形＋のをきっかけとして / 名詞＋がきっかけで","ko":"名詞＋をきっかけに（して） / 名詞＋をきっかけとして / 動普通形＋のをきっかけに（して） / 動普通形＋のをきっかけとして / 名詞＋がきっかけで"},"examples":[{"ja":"結婚をきっかけに新居を買った。","en":"We bought a new house after getting married.","ko":"결혼을 계기로 새집을 샀다."}],"similar":[]},
  {"id":"d1725293496004","pattern":"〜をもとに／をもとにして／をもとにした","core":"をもとに","blankTarget":"をもとに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"材料、素材、根拠となるもの、参考となるものを表します。 漢字は「基（もと）」です。","en":"based on; using ... as a basis","ko":"…을 바탕으로; …을 토대로"},"formation":{"ja":"名詞＋をもとに（して） / 名詞＋をもとにした＋名詞","en":"名詞＋をもとに（して） / 名詞＋をもとにした＋名詞","ko":"名詞＋をもとに（して） / 名詞＋をもとにした＋名詞"},"examples":[{"ja":"これは実話をもとに描いた絵本です。","en":"This is a picture book based on a true story.","ko":"이것은 실화를 바탕으로 그린 그림책입니다."}],"similar":[]},
  {"id":"d1725293496001","pattern":"〜を兼ねて(かねて)","core":"を兼ねて(かねて)","blankTarget":"をかねて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"本来の目的とは別に、他の目的も同時に存在していることを表します。 前件にはその他の目的を表す語が接続されます。","en":"combining ... with; also serving as; while also ...","ko":"…을 겸해서; …도 겸하여"},"formation":{"ja":"名詞＋を兼ねて","en":"名詞＋を兼ねて","ko":"名詞＋を兼ねて"},"examples":[{"ja":"ストレス発散をかねて半身浴する。","en":"I take a half bath, which also helps relieve stress.","ko":"스트레스 해소를 겸해서 반신욕을 한다."}],"similar":[]},
  {"id":"d1725293496003","pattern":"〜を巡って／を巡り／を巡る","core":"を巡って","blankTarget":"を巡り","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～を巡って」はその事柄に対して多くの人が関心を持ち、それが人々の話題の中心に位置することを強調する表現です。 後件には「話し合う」「議論する」「争う」のような、大人数で行われる動作の動詞がきます。 ◯日本語の副詞に関して質問したいのですが、宜しいですか？✕日本語の副詞を巡って質問したいのですが、宜しいですか？ ◯日本語の副詞の分類に関して研究しています。 ✕日本語の副詞の分類を巡って研究しています。 ◯日本語の副詞の分類を巡って、研究者の間で議論が行われている。 ◯日本語の副詞の分類に関して、研究者の間で議論が行われている。 上の例文において「質問する」「研究する」などはその人だけが行う動作ですので「～を巡って」を使うと不自然になります。一方、「議論」は大人数で行うものですので「～を巡って」を使うのが自然です。これらの場合、「～に関して」「～について」などに言い換えることができます。","en":"over; concerning; in a dispute or discussion about","ko":"…을 둘러싸고; …을 놓고"},"formation":{"ja":"名詞＋を巡って／を巡り / 名詞＋を巡る＋名詞 / 名詞＋を巡っての＋名詞","en":"名詞＋を巡って／を巡り / 名詞＋を巡る＋名詞 / 名詞＋を巡っての＋名詞","ko":"名詞＋を巡って／を巡り / 名詞＋を巡る＋名詞 / 名詞＋を巡っての＋名詞"},"examples":[{"ja":"世界一の称号を巡り、今年も世界の強豪たちが一堂に集結した。","en":"Contenders from around the world gathered again this year to compete for the title of world's best.","ko":"세계 1위라는 칭호를 둘러싸고 올해도 세계의 강호들이 한자리에 모였다."}],"similar":[]},
  {"id":"d1725293496005","pattern":"〜を除いて／を除き","core":"を除いて","blankTarget":"を除き","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある範囲から一部の要素を除外することを表します。","en":"except for; excluding; apart from","ko":"…을 제외하고; …을 빼고"},"formation":{"ja":"名詞＋を除いて／を除き","en":"名詞＋を除いて／を除き","ko":"名詞＋を除いて／を除き"},"examples":[{"ja":"館内は一部を除き撮影できます。","en":"Photography is allowed inside the building except in certain areas.","ko":"관내에서는 일부 구역을 제외하고 촬영할 수 있습니다."}],"similar":[]},
  {"id":"d1725293496007","pattern":"〜を通じて(つうじて)／を通して(とおして)","core":"を通じて(つうじて)","blankTarget":"を通じて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"２つの意味があります。 ①期間 時間名詞に接続して、その間の期間を表します。 ②仲介、手段 「動詞辞書形＋ことを通じて／通して」のときは、一般的に後項では「学ぶ」「知る」など動詞が用いられます。","en":"through; via; by means of; throughout (a period)","ko":"…을 통해; …을 매개로; …동안 내내"},"formation":{"ja":"名詞＋を通じて / 名詞＋を通して / 動詞辞書形＋ことを通じて / 動詞辞書形＋ことを通して","en":"名詞＋を通じて / 名詞＋を通して / 動詞辞書形＋ことを通じて / 動詞辞書形＋ことを通して","ko":"名詞＋を通じて / 名詞＋を通して / 動詞辞書形＋ことを通じて / 動詞辞書形＋ことを通して"},"examples":[{"ja":"SNSなどを通じて見知らぬ人に会うことはしばしば危険を伴う。","en":"Meeting strangers through social media and the like often involves danger.","ko":"SNS 등을 통해 모르는 사람을 만나는 것은 종종 위험을 수반한다."}],"similar":[]},
  {"id":"d1725293496000","pattern":"〜を踏まえ／を踏まえて／を踏まえた","core":"を踏まえ","blankTarget":"を踏まえて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"現状や実情、反省、結果、状況などといった名詞をとり、それらを根拠や前提、判断材料として何か物事を行うことを述べる文型です。","en":"based on; in light of; taking ... into account","ko":"…을 바탕으로; …을 고려하여; …을 감안하여"},"formation":{"ja":"名詞＋を踏まえ（て） / 名詞＋を踏まえた＋名詞","en":"名詞＋を踏まえ（て） / 名詞＋を踏まえた＋名詞","ko":"名詞＋を踏まえ（て） / 名詞＋を踏まえた＋名詞"},"examples":[{"ja":"先学期の反省を踏まえて、今学期はやり方を変えてみる。","en":"Based on my reflections on last semester, I'll try a different approach this semester.","ko":"지난 학기의 반성을 바탕으로 이번 학기에는 방법을 바꿔 보겠다."}],"similar":[]},
  {"id":"d1725293496006","pattern":"〜を問わず／は問わず","core":"を問わず","blankTarget":"を問わず","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"前件の結果や状態に左右されないことを表します。 「～にかかわらず」と同じ意味です。 学歴、国籍、成績、理由、合否、成否など複数の側面がある単語と結び付きます。","en":"regardless of; irrespective of; no matter (what)","ko":"…을 막론하고; …과 상관없이; …을 불문하고"},"formation":{"ja":"名詞＋（を）問わず / 名詞＋は問わず","en":"名詞＋（を）問わず / 名詞＋は問わず","ko":"名詞＋（を）問わず / 名詞＋は問わず"},"examples":[{"ja":"殺人というのは理由を問わず許されない行為だ。","en":"Murder is an unforgivable act, whatever the reason.","ko":"살인은 이유를 막론하고 용납될 수 없는 행위다."}],"similar":[]},
  {"id":"d1725293495884","pattern":"〜兼ねない(かねない)","core":"兼ねない(かねない)","blankTarget":"かねない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"良くない可能性や危険性があることを表します。 話者の物事に対する負の評価として使います。","en":"might well ...; there is a real risk that; could easily (do something bad)","ko":"…할 수도 있다; …할 우려가 있다; 자칫 …할 수 있다"},"formation":{"ja":"動ます形＋兼ねない","en":"動ます形＋兼ねない","ko":"動ます形＋兼ねない"},"examples":[{"ja":"彼女は信用できないので秘密を漏らしかねない。","en":"I can't trust her, so she might well leak the secret.","ko":"그녀는 믿을 수 없어서 비밀을 누설할지도 모른다."}],"similar":[]},
  {"id":"d1725293495885","pattern":"〜兼ねる(かねる)","core":"兼ねる(かねる)","blankTarget":"見るに見かねて","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～したくてもできない」「～したくても難しい」という意味で使われます。できない理由は主に心理的なものが原因です。 他人のお願いや命令に対して婉曲的に断る表現としても使え、その場合は比較的丁寧な印象を与えます。 直接「できない」と言うことを避ける場面で使えます。 「見るに見かねて」は慣用的な表現で、見ることができないくらいかわいそうな状況であることを表します。","en":"cannot bring oneself to; find it hard to; be unable to (for psychological reasons)","ko":"…하기 어렵다; …할 수 없다; …하기가 곤란하다"},"formation":{"ja":"動ます形＋かねる","en":"動ます形＋かねる","ko":"動ます形＋かねる"},"examples":[{"ja":"怪我した子猫を見るに見かねて、動物病院へ連れて行った。","en":"I couldn't bear to watch the injured kitten, so I took it to the animal hospital.","ko":"다친 새끼 고양이를 차마 보고만 있을 수 없어 동물병원에 데려갔다."}],"similar":[]},
  {"id":"d1725293495876","pattern":"〜限り／ない限り","core":"限り","blankTarget":"限り","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある状態が継続している期間を表します。 前項で述べる状態が継続している間は後項が成り立ちます。前項が成り立たなければ、後項は必ずしも必要ではありません。","en":"as long as; provided that; unless","ko":"…는 한; …지 않는 한"},"formation":{"ja":"動詞辞書形＋限り（は） / 動ている形＋限り（は） / イ形容詞＋限り（は） / ナ形容詞語幹＋な／である＋限り（は） / 名詞＋の／である＋限り（は）","en":"動詞辞書形＋限り（は） / 動ている形＋限り（は） / イ形容詞＋限り（は） / ナ形容詞語幹＋な／である＋限り（は） / 名詞＋の／である＋限り（は）","ko":"動詞辞書形＋限り（は） / 動ている形＋限り（は） / イ形容詞＋限り（は） / ナ形容詞語幹＋な／である＋限り（は） / 名詞＋の／である＋限り（は）"},"examples":[{"ja":"ここに居る限り、台風にも地震にも脅かされることはないだろう。","en":"As long as we stay here, we won't be threatened by typhoons or earthquakes.","ko":"여기 있는 한 태풍이나 지진에 위협받는 일은 없을 것이다."}],"similar":[]},
  {"id":"d1725293495863","pattern":"〜甲斐(がい)","core":"甲斐(がい)","blankTarget":"生き甲斐","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「～甲斐がある」「～甲斐がない」の形を取り、価値や意味があることを表します。 「甲斐」は本来「かい」と読みますが、動ます形と接続するときは「がい」と読みます。","en":"worth (doing); value; reward for one's effort","ko":"…하는 보람; …한 가치"},"formation":{"ja":"動ます形＋甲斐（がい）","en":"動ます形＋甲斐（がい）","ko":"動ます形＋甲斐（がい）"},"examples":[{"ja":"マラソンは私の生き甲斐だ。","en":"Running marathons is what makes my life worth living.","ko":"마라톤은 내 삶의 보람이다."}],"similar":[]},
  {"id":"d1725293495880","pattern":"〜甲斐がある／〜甲斐があって／〜甲斐がない／〜甲斐もなく","core":"甲斐がある","blankTarget":"た甲斐があって","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「甲斐がある」「甲斐があって」は効果や価値があることを、「甲斐がない」「甲斐もなく」はないことを表します。 「甲斐がある」「甲斐がない」は文末で使い、「甲斐があって」「甲斐もなく」はその後に何らかの文が続きます。 「動ます形＋甲斐」の形を取るときは、「～がい」と読みます。 詳しくは「【Ｎ２文法】～甲斐（がい）」で。","en":"be worth it; pay off; be rewarded (or, in the negative, be in vain)","ko":"…한 보람이 있다; …한 보람이 없다"},"formation":{"ja":"名詞＋の＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動た形＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動ます形＋甲斐（一部の動詞）","en":"名詞＋の＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動た形＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動ます形＋甲斐（一部の動詞）","ko":"名詞＋の＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動た形＋甲斐がある／甲斐があって／甲斐がない／甲斐もなく / 動ます形＋甲斐（一部の動詞）"},"examples":[{"ja":"筋トレ頑張った甲斐があって１週間で２キロ落ちた。","en":"My efforts at strength training paid off: I lost two kilograms in a week.","ko":"근력 운동을 열심히 한 보람이 있어서 일주일 만에 2킬로가 빠졌다."}],"similar":[]},
  {"id":"d1725293496017","pattern":"〜済み／済(ずみ)","core":"済み","blankTarget":"済み","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"名詞に接続して、既に終わっていることを表します。 動詞の連用形（動詞を名詞化したもの）にも接続できますが、サ変動詞語幹や漢語に接続できるケースが多いです。 書き言葉的。 「用済み（已经使用过的…）」は慣用表現です。 例文（11）のように人に対して用いることもでき、「もう必要なくなった」という意味になります。 織り込み済み（预料之中）","en":"already done; completed; settled","ko":"…완료; …끝남; 이미 …된"},"formation":{"ja":"名詞＋済み／済","en":"名詞＋済み／済","ko":"名詞＋済み／済"},"examples":[{"ja":"決済済みのご予約をキャンセルした場合、キャンセル料が発生します。","en":"If you cancel a reservation that has already been paid for, a cancellation fee will apply.","ko":"결제가 완료된 예약을 취소하실 경우 취소 수수료가 발생합니다."}],"similar":[]},
  {"id":"d1725293495960","pattern":"〜次第(しだい)","core":"次第(しだい)","blankTarget":"次第です","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「名詞＋次第だ」の文型を取り、結果や状況の変化がそのものの性質や意向に委ねられていることを表します。","en":"depends entirely on; is up to; hinges on","ko":"…에 달려 있다; …하기 나름이다"},"formation":{"ja":"名詞＋次第だ","en":"名詞＋次第だ","ko":"名詞＋次第だ"},"examples":[{"ja":"信じるか信じないかはあなた次第です。","en":"Whether you believe it or not is up to you.","ko":"믿을지 말지는 당신에게 달려 있습니다."}],"similar":[]},
  {"id":"d1725293495861","pattern":"〜得ない","core":"得ない","blankTarget":"えない","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"状況的に不可能であることを表します。 能力可能は表せません。 可能形「～れない／られない」が可能性がないことを表す場合、お互いに言い換えることができます。 ◯日本語を話せない。 ✕日本語を話し得ない。 「～得ない」は比較的硬い表現ですが、「ありえない」は口語としても頻繁に使われます。","en":"cannot possibly; impossible to; cannot (by the nature of things)","ko":"…할 수 없다; …하는 것이 불가능하다"},"formation":{"ja":"動ます形＋得ない","en":"動ます形＋得ない","ko":"動ます形＋得ない"},"examples":[{"ja":"あんなひどいことを言っておいて、今さら謝るなんてありえない。","en":"After saying such awful things, it's unthinkable that he'd apologize now.","ko":"그런 심한 말을 해 놓고 이제 와서 사과한다니 있을 수 없는 일이다."}],"similar":[]},
  {"id":"d1725293495862","pattern":"〜得る","core":"得る","blankTarget":"える","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"状況可能を表します。 能力可能は表せません。 ◯日本語を話せる。 ✕日本語を話し得る。 基本的には「うる」と読みますが、「ありうる／ありえる」「起こりうる／起こりえる」「なりうる／なりえる」は例外的にどちらでも正しいです。 「～得る」は比較的硬い表現ですが、「ありえる」は口語としても頻繁に使われます。","en":"can; may; is possible; is conceivable","ko":"…할 수 있다; …할 가능성이 있다"},"formation":{"ja":"動ます形＋得る","en":"動ます形＋得る","ko":"動ます形＋得る"},"examples":[{"ja":"宇宙はこんなにも広いんだから、宇宙人の存在はきっとありえる話だ。","en":"The universe is so vast that the existence of aliens is surely a real possibility.","ko":"우주가 이렇게 넓으니 외계인의 존재는 충분히 있을 수 있는 이야기다."}],"similar":[]},
  {"id":"d1725293495953","pattern":"〜抜きで／抜きの／は抜きで／は抜きにして","core":"抜きで","blankTarget":"抜きで","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"そのものを省略したり、取り除くことを表します。後項にはその状態で何かを行うことが述べられます。","en":"without; leaving out; setting ... aside","ko":"…을 빼고; …없이; …을 제외하고"},"formation":{"ja":"名詞＋抜きで / 名詞＋抜きの / 名詞＋は抜きで / 名詞＋は抜きにして / 名詞＋を抜きにして","en":"名詞＋抜きで / 名詞＋抜きの / 名詞＋は抜きで / 名詞＋は抜きにして / 名詞＋を抜きにして","ko":"名詞＋抜きで / 名詞＋抜きの / 名詞＋は抜きで / 名詞＋は抜きにして / 名詞＋を抜きにして"},"examples":[{"ja":"体臭がひどいのは冗談抜きでＮＧ。","en":"Joking aside, bad body odor is a total no-go.","ko":"농담 빼고, 심한 체취는 무조건 안 된다."}],"similar":[]},
  {"id":"d1725293495954","pattern":"〜抜く","core":"抜く","blankTarget":"抜いた","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"動作性の動詞に接続して、その動作の完遂を表します。 動作の完遂にあたって何らかの困難があり、それを克服したニュアンスを持ちます。","en":"do ... to the very end; carry through; endure to the last","ko":"…을 끝까지 해내다; …을 완수하다"},"formation":{"ja":"動ます形＋抜く","en":"動ます形＋抜く","ko":"動ます形＋抜く"},"examples":[{"ja":"苦しみながらも１５００ｍを何とか走り抜いた。","en":"Despite the pain, I somehow managed to run the full 1500 meters.","ko":"괴로우면서도 1500미터를 어떻게든 끝까지 달렸다."}],"similar":[]},
  {"id":"d1725293495868","pattern":"〜反面(半面)","core":"反面(半面)","blankTarget":"反面","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「反面」とは別の面という意味で、ここから転じて、一つの事柄についての相反する側面を対比的に表すときに使います。一つの事柄の２つの側面に触れるときに使われるため、必ず同一主語分でなければいけません。 前項がプラスの内容のとき、後項ではマイナスの内容がきます。その逆も同じです。","en":"on the other hand; conversely; while (contrasting two sides of one thing)","ko":"반면에; 다른 한편으로는"},"formation":{"ja":"動詞普通形＋反面 / い形容詞普通形＋反面 / な形容詞＋な／である＋反面 / 名詞＋である反面 / その＋反面（では）","en":"動詞普通形＋反面 / い形容詞普通形＋反面 / な形容詞＋な／である＋反面 / 名詞＋である反面 / その＋反面（では）","ko":"動詞普通形＋反面 / い形容詞普通形＋反面 / な形容詞＋な／である＋反面 / 名詞＋である反面 / その＋反面（では）"},"examples":[{"ja":"水に強い反面、熱に弱い。","en":"It is water-resistant, but weak against heat.","ko":"물에는 강한 반면 열에는 약하다."}],"similar":[]},
  {"id":"d1747573317848","pattern":"いわゆる〜","core":"いわゆる〜","blankTarget":"いわゆる","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"「いわゆる」の後ろに”世間で一般的に呼ばれている言い方”である名詞を後接させて、「一般に～と呼ばれているもの」という意味を表します。多くの場合、「いわゆる」に後接する名詞の呼び方、あるいはその名詞が表すものに対して軽蔑のニュアンスが現れます。例えば「いわゆる闇バイト」というと、「闇バイト」に対して否定的な感情が現れます。","en":"so-called; what is generally called","ko":"이른바; 소위"},"formation":{"ja":"いわゆる＋名詞","en":"いわゆる＋名詞","ko":"いわゆる＋名詞"},"examples":[{"ja":"いわゆる“闇バイト”ってやつ、条件悪すぎて笑えない。","en":"This so-called \"dark part-time job\" has such terrible conditions it's not even funny.","ko":"이른바 '어둠의 아르바이트'라는 것, 조건이 너무 나빠서 웃을 수도 없다."}],"similar":[]},
  {"id":"d1725293496009","pattern":"よくも〜ものだ／よくも〜","core":"よくも〜ものだ","blankTarget":"よくも","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある行為に対する称賛や非難を表します。 称賛の仕方によっては皮肉にもなります。 動詞に接続する場合、「よくも＋動詞」にするとやや不自然となります。 「よくも」には「こんな／そんな／あんな」が続きやすいです。 口語では「よくもまあ～もんだ」などということも多いです。","en":"how dare ...; to actually ...; what nerve","ko":"…하다니; 어찌 그리 …할 수 있나; …할 줄이야"},"formation":{"ja":"よく＋動詞可能形＋ものだ / よく＋動詞た形＋ものだ / よく＋動詞ていた形＋ものだ / よくも＋こんな／そんな／あんな","en":"よく＋動詞可能形＋ものだ / よく＋動詞た形＋ものだ / よく＋動詞ていた形＋ものだ / よくも＋こんな／そんな／あんな","ko":"よく＋動詞可能形＋ものだ / よく＋動詞た形＋ものだ / よく＋動詞ていた形＋ものだ / よくも＋こんな／そんな／あんな"},"examples":[{"ja":"よくもこんだけ図々しい嘘がつけるものだ。","en":"How can you tell such a brazen lie?","ko":"어쩜 이렇게 뻔뻔한 거짓말을 할 수 있지."}],"similar":[]},
  {"id":"d1725293495873","pattern":"一向に〜ない","core":"一向に〜ない","blankTarget":"一向に","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"ある物事が発生・実現することを長い時間努力をして待ち望んでいたのにも関わらず、結局実現しなかったことを表します。 実現しなかったことに対する焦りや疑念の感情を含むのが特徴です。 「一向に構わない（没关系,不在乎）」は慣用表現で、上記のような意味はありません。 後件には必ず否定形を伴います。","en":"not at all; not in the least; far from (happening)","ko":"전혀 …지 않다; 좀처럼 …지 않다"},"formation":{"ja":"一向に＋動ない形＋ない","en":"一向に＋動ない形＋ない","ko":"一向に＋動ない形＋ない"},"examples":[{"ja":"二人の関係が一向に進展しないのでじれったくなる。","en":"Their relationship isn't progressing at all, which is frustrating.","ko":"두 사람의 관계가 전혀 진전되지 않아서 답답해진다."}],"similar":[]},
  {"id":"d1725293495907","pattern":"見るからに〜／見るからにして〜","core":"見るからに〜","blankTarget":"見るからに","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"外見やその様子から一目で間違いなくそうであると判断できることを表します。 後件には「～そうだ」が呼応しやすいです。","en":"obviously from appearance; at first glance; just by looking","ko":"보기에도; 딱 봐도; 겉보기에"},"formation":{"ja":"見るからに＋形容 / 見るからにして＋形容","en":"見るからに＋形容 / 見るからにして＋形容","ko":"見るからに＋形容 / 見るからにして＋形容"},"examples":[{"ja":"あの男、見るからにヤバそう。","en":"That guy looks trouble at first glance.","ko":"저 남자, 딱 봐도 위험해 보인다."}],"similar":[]},
  {"id":"d1725293495879","pattern":"限りなく〜に近い","core":"限りなく〜に近い","blankTarget":"限りなく","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"接続される名詞が持つ性質に近似していることを表します。","en":"as close to ... as possible; virtually; next to","ko":"한없이 …에 가깝다; 거의 …에 가깝다"},"formation":{"ja":"限りなく＋名詞＋に近い","en":"限りなく＋名詞＋に近い","ko":"限りなく＋名詞＋に近い"},"examples":[{"ja":"あいつは限りなく黒に近いグレーだ。","en":"He's gray, but as close to black as it gets.","ko":"그 녀석은 한없이 검정에 가까운 회색이다."}],"similar":[]},
  {"id":"d1725293495874","pattern":"今でこそ〜が","core":"今でこそ〜が","blankTarget":"今でこそ","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"今は何も問題がなくなったが以前は重大な問題だったこと、あるいは今は当然のことだが以前はそうではなかったことを表します。 「今でこそ」の後には現在の状況を述べ、後件には過去の状況を述べます。 この文型は常に現在を起点にして過去のことを述べるときに用います。 後件に逆接を伴わず単独で用いることもできます。例文（７）（８）。","en":"nowadays ... but (in the past); it is only now that ...","ko":"지금이야 …이지만; 지금은 …이지만"},"formation":{"ja":"今でこそ＋文の普通体＋が","en":"今でこそ＋文の普通体＋が","ko":"今でこそ＋文の普通体＋が"},"examples":[{"ja":"Ａ社は今でこそカメラで有名になっているが、創業当時は文房具を作っていた。","en":"Company A is famous for cameras now, but when it was founded it made stationery.","ko":"A사는 지금이야 카메라로 유명하지만 창업 당시에는 문구를 만들고 있었다."}],"similar":[]},
  {"id":"d1725293495875","pattern":"今にも〜そうだ","core":"今にも〜そうだ","blankTarget":"今にも","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"緊迫した状況下で、ある物事がもうすぐ発生・実現することを表します。","en":"about to; on the verge of; any moment now","ko":"금방이라도 …할 것 같다; 당장이라도"},"formation":{"ja":"今にも＋動ます形＋そうだ","en":"今にも＋動ます形＋そうだ","ko":"今にも＋動ます形＋そうだ"},"examples":[{"ja":"今にも空を飛べそうなくらい嬉しい。","en":"I'm so happy I feel as if I could fly right now.","ko":"당장이라도 하늘을 날 수 있을 것만큼 기쁘다."}],"similar":[]},
  {"id":"d1725293495883","pattern":"必ずしも〜とは限らない／必ずしも〜わけではない","core":"必ずしも〜とは限らない","blankTarget":"必ずしも","reading":"","quiz":true,"tag":"general","level":"N2","meaning":{"ja":"この文法はよく「～からといって」「～たとしても」の後に続きます。「～からといって、必ずしも～ない（虽说…也未必…）」 「～ないとは限らない（…未必不）」等と否定形に接続することもできます。（９）（10）","en":"not necessarily; not always","ko":"반드시 …라고는 할 수 없다; 꼭 …인 것은 아니다"},"formation":{"ja":"（必ずしも＋）動詞普通形＋とは限らない / （必ずしも＋）名詞＋（だ）とは限らない / （必ずしも＋）な形容詞語幹＋（だ）とは限らない / （必ずしも＋）い形容詞普通形＋とは限らない / 必ずしも＋動詞普通形＋（という）わけではない","en":"（必ずしも＋）動詞普通形＋とは限らない / （必ずしも＋）名詞＋（だ）とは限らない / （必ずしも＋）な形容詞語幹＋（だ）とは限らない / （必ずしも＋）い形容詞普通形＋とは限らない / 必ずしも＋動詞普通形＋（という）わけではない","ko":"（必ずしも＋）動詞普通形＋とは限らない / （必ずしも＋）名詞＋（だ）とは限らない / （必ずしも＋）な形容詞語幹＋（だ）とは限らない / （必ずしも＋）い形容詞普通形＋とは限らない / 必ずしも＋動詞普通形＋（という）わけではない"},"examples":[{"ja":"いつも笑顔だからといって、必ずしも良い人だとは限らない。","en":"Just because someone is always smiling doesn't necessarily mean they're a good person.","ko":"항상 웃는 얼굴이라고 해서 반드시 좋은 사람이라고는 할 수 없다."}],"similar":[]}
]);
